INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2091', 'spa', 'Disposición, preparación; estado de estar equipado y listo para la acción', 'Este sustantivo designa la condición de estar listo o preparado, ya sea para el servicio, la acción o la oportunidad. En Efesios 6:15, aparece en el pasaje de la armadura de Dios, donde los pies de los creyentes están calzados ''con la disposición del evangelio de la paz.'' La palabra enfatiza no una espera pasiva, sino una preparación activa: estar equipado y dispuesto a compartir las buenas nuevas en todo momento, como el soldado romano que mantiene sus sandalias listas para el despliegue inmediato.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2092', 'spa', 'Listo, preparado, a la mano: que describe un estado de preparación para una acción o evento, o la disposición de estar preparado. Adjetivo que signifi', 'Listo, preparado, a la mano: que describe un estado de preparación para una acción o evento, o la disposición de estar preparado. Adjetivo que significa «listo» o «preparado», usado en los Evangelios Sinópticos para banquetes de boda que están listos (Mateo 22:4, 8), vírgenes prudentes que están preparadas (Mateo 25:10) y discípulos que deben estar alerta (Mateo 24:44). En un pasaje paulino (2 Corintios 10:6), la palabra adquiere un matiz más abstracto y nominal —una disposición o voluntad de actuar— donde el español cambia a «preparación», insinuando una disposición interior más que un estado externo de cosas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2093', 'spa', 'con prontitud, en disposición; forma adverbial que indica estado de preparación o voluntad', 'Este adverbio deriva de ἑτοῖμος (listo, preparado) e indica un estado de disposición o voluntad para actuar. Describe estar preparado de antemano, tener algo a la mano o estar dispuesto a obrar. En el Nuevo Testamento aparece en contextos de prontitud: la disposición de Pablo a sufrir (Hechos 21:13), su preparación para apoyar a los corintios (2 Corintios 12:14) y la inminencia del juicio divino (1 Pedro 4:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2094', 'spa', 'Año — unidad de tiempo que mide un ciclo anual completo, usada para edades, duraciones y cómputo histórico', 'Ἔτος es la palabra griega estándar para «año» y aparece 49 veces en el Nuevo Testamento para medir el paso del tiempo en vidas humanas e historia sagrada. Indica la edad de personas —Jesús a los doce años en el templo (Lc 2:42), la mujer con flujo de sangre que padecía desde hacía doce años (Mc 5:25)— y duraciones de peso profético o teológico: los tres años de Pablo en Arabia antes de encontrarse con los apóstoles (Gá 1:18), los cien años de Abraham al nacer Isaac (Ro 4:19). La expresión idiomática κατ'' ἔτος («cada año», Lc 2:41) evoca el lenguaje litúrgico de la Septuaginta. Las traducciones convergen sin variación: español «años», francés «an/année», alemán «Jahr/Jahre».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2095', 'spa', 'Bien; adverbio de aprobación o competencia, que indica algo hecho correcta, cabal o virtuosamente.', 'Adverbio griego versátil que señala aprobación, competencia o bondad moral. En el habla cotidiana funciona como el español ''bien'', describiendo una acción realizada correctamente o un estado justo y apropiado. En los Evangelios adquiere una fuerza distintiva de elogio cuando un señor se dirige a su siervo fiel: ''¡Bien hecho, siervo bueno y fiel!'' (Mt 25:21, 23; Lc 19:17). En otros pasajes simplemente significa ''rectamente'' o ''como conviene'' (Hch 15:29; Ef 6:3), sin la carga exclamativa de la parábola de los talentos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2097', 'spa', 'Anunciar buenas nuevas, predicar el evangelio; en voz pasiva, recibir la proclamación de buenas nuevas', 'Un término propiamente bíblico construido sobre la raíz que significa «buen mensaje», usado a lo largo del Nuevo Testamento para la actividad central de la misión cristiana primitiva: proclamar las buenas nuevas. En el anuncio del ángel a Zacarías (Lc 1:19) y a los pastores (Lc 2:10), la palabra porta su sentido más pleno de noticia enviada del cielo. Jesús mismo la aplica programáticamente en Lucas 4:18, citando Isaías 61. La voz pasiva, presente en pasajes como Mateo 11:5 y Hebreos 4:2, traslada la atención a los destinatarios —los pobres, los enfermos y quienes oyen pero deben también recibir con fe—.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2098', 'spa', 'Buenas nuevas; el evangelio — el anuncio de la acción salvífica de Dios en Cristo', 'En el griego clásico, εὐαγγέλιον significaba originalmente la recompensa dada al mensajero que traía buenas noticias, o la ofrenda de acción de gracias al recibirlas. Para la época del Nuevo Testamento se había convertido en el mensaje mismo: el «evangelio», la proclamación de la obra redentora de Dios por medio de Jesucristo. Marcos abre toda su narración con esta palabra (Mc 1:1) y Pablo la emplea como término casi técnico para la predicación apostólica (Ro 1:16; 1 Co 15:1). El español «evangelio», el francés «évangile» y el alemán «Evangelium» descienden directamente del griego, testimoniando la centralidad perdurable del término en el vocabulario cristiano a través de siglos y culturas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2099', 'spa', 'evangelista; quien proclama las buenas nuevas del evangelio', 'Este sustantivo designa a un portador de buenas nuevas, específicamente a quien proclama el mensaje del evangelio. Aunque todos los creyentes comparten la fe, el término «evangelista» parece señalar un rol o don ministerial concreto en la iglesia primitiva, distinto del de apóstoles, profetas y pastores-maestros. Felipe es llamado explícitamente «el evangelista» (Hechos 21:8), y a Timoteo se le exhorta a «hacer obra de evangelista» (2 Timoteo 4:5). El término identifica a quienes tienen como función principal la proclamación del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2100', 'spa', 'agradar, ser agradable a; obtener aprobación o satisfacción', 'Este verbo significa ser grato o aceptable ante alguien, obtener su favor o aprobación. En el Nuevo Testamento aparece exclusivamente en Hebreos, donde describe el acto de agradar a Dios mediante la fe. El traslado de Enoc es evidencia de que agradó a Dios (11:5), la fe es necesaria para agradarle (11:6), y ciertos sacrificios le son agradables (13:16). El término enfatiza aquello que satisface o deleita a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2101', 'spa', 'Agradable, aceptable; describe la conducta o las personas que resultan gratas y aprobadas, especialmente por Dios.', 'Adjetivo que significa ''agradable'' o ''aceptable'', empleado casi exclusivamente para aquello que complace a Dios. Pablo exhorta a los creyentes a presentar sus cuerpos como sacrificios vivos, santos y agradables a Dios (Ro 12:1), a discernir lo que es agradable al Señor (Ro 12:2; Ef 5:10), y a proponerse como meta serle gratos (2 Co 5:9). En Hebreos 13:21, Dios capacita a los creyentes para toda buena obra que sea agradable ante sus ojos. El término transmite una aprobación genuina, no mera tolerancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2102', 'spa', 'De manera aceptable, agradablemente; de un modo que obtiene aprobación o complace', 'Este adverbio describe acciones realizadas de un modo que agrada u obtiene la aceptación de otro. En Hebreos 12:28, modifica la manera en que los creyentes deben servir a Dios: de forma aceptable, con reverencia y temor reverente. La palabra conlleva la idea de cumplir las expectativas y ganar aprobación, no mediante el mero cumplimiento externo, sino a través del espíritu con el cual se ofrece el servicio. Es una adoración que Dios recibe favorablemente porque honra tanto su santidad como su gracia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2103', 'spa', 'Eubulo, nombre propio que significa ''buen consejero'' o ''bien aconsejado''; un creyente en Roma', 'Eubulo fue uno de los cuatro creyentes que enviaron saludos a Timoteo a través de la última carta de Pablo (2 Timoteo 4:21). El nombre en sí significa ''bien aconsejado'' o ''de buen consejo,'' aunque no sabemos nada más sobre este individuo. Representa a los fieles anónimos que rodearon a Pablo durante su último encarcelamiento en Roma, manteniendo la comunión y apoyando el ministerio del apóstol cuando otros se habían apartado, un testimonio silencioso de lealtad cristiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2104', 'spa', 'noble, de alta cuna; de nacimiento distinguido o carácter elevado', 'Este adjetivo describe a quienes son de nacimiento noble o posición elevada, ya sea por linaje o por carácter. En el uso clásico abarca tanto la nobleza literal de origen aristocrático como la nobleza metafórica de espíritu. En el Nuevo Testamento aparece en contextos variados: un hombre noble que parte a recibir un reino (Lucas 19:12), el carácter noble de los bereanos al examinar las Escrituras (Hechos 17:11), y la ironía de que no muchos de nacimiento noble son llamados por Dios (1 Corintios 1:26).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2105', 'spa', 'Buen tiempo, cielos despejados; condiciones atmosféricas tranquilas sin tormenta ni lluvia', 'Este sustantivo describe el tiempo apacible o despejado, lo opuesto a condiciones tormentosas. En el griego clásico podía denotar metafóricamente tranquilidad o paz interior, pero en el Nuevo Testamento aparece solo en sentido literal. Jesús lo emplea en Mateo 16:2 al responder a los fariseos y saduceos que sabían interpretar las señales del clima (un cielo rojo que anuncia buen tiempo), pero no lograban discernir las señales de los tiempos. Representa la calma en ausencia de la tormenta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2106', 'spa', 'Complacerse en, deleitarse; consentir, determinar o resolver hacer algo', 'Complacerse en, deleitarse; consentir, determinar o resolver hacer algo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2107', 'spa', 'Beneplácito, voluntad bondadosa o deleite; especialmente el propósito soberano y benévolo de Dios hacia la humanidad.', 'Εὐδοκία capta algo profundamente personal del corazón de Dios: su beneplácito, su deleite voluntario, su propósito lleno de gracia. Cuando los ángeles proclaman paz en la tierra a los hombres de su εὐδοκία (Lc 2:14), la palabra transmite no una simple aprobación sino una intención activa y gozosa. Jesús mismo la emplea en oración: ''Sí, Padre, porque así te agradó'' (Mt 11:26; Lc 10:21), revelando una voluntad soberana que es también cálida y personal. Pablo la aplica tanto al propósito predestinador de Dios (Ef 1:5, 9) como a su propio anhelo por Israel (Ro 10:1), mostrando que el término conecta la soberanía divina con el anhelo humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2109', 'spa', 'Hacer el bien, conferir beneficios, obrar con benevolencia; realizar actos concretos de bondad y ayuda', 'Este verbo capta la benevolencia activa: no simplemente desear el bien, sino realmente hacerlo a favor de otros. Lucas lo emplea al resumir el ministerio de Jesús: «anduvo haciendo bienes y sanando a todos los oprimidos por el diablo» (Hechos 10:38). La palabra enfatiza actos concretos de bondad y auxilio, a menudo con la connotación de alguien con mayores recursos o poder que bendice a quienes tienen menos. Es la beneficencia llevada a la práctica, no mera intención.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2110', 'spa', 'Bienhechores, patronos; quienes confieren beneficios o realizan buenas obras a favor de otros', 'En el mundo grecorromano, «bienhechor» era tanto una descripción como un título oficial conferido a gobernantes y personas adineradas que financiaban obras públicas, distribuían grano o servían de algún modo a sus comunidades. Jesús hace referencia a este sistema en Lucas 22:25, señalando que los gobernantes gentiles que ejercen autoridad sobre otros son llamados bienhechores, a menudo con ironía, pues su «generosidad» servía para consolidar poder y exigir gratitud. El reino de Cristo invierte esta lógica: la grandeza nace del servicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2111', 'spa', 'Apto, adecuado, útil; apropiado o bien dispuesto para un propósito determinado', 'Este adjetivo describe algo bien dispuesto, apto o adecuado para cumplir un propósito. En el griego clásico se aplicaba a lo convenientemente ubicado, oportuno o bien ajustado. En el Nuevo Testamento aparece en contextos de aptitud: la idoneidad para el servicio del reino (Lucas 9:62), la utilidad de la sal (Lucas 14:35) y la fecundidad de la tierra bendecida (Hebreos 6:7). El término subraya la disposición apropiada y la preparación para el uso previsto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2112', 'spa', 'Inmediatamente, al instante, al punto; adverbio temporal que indica acción sin demora', 'Εὐθέως es el adverbio por excelencia de Marcos, que aparece con llamativa frecuencia en el segundo Evangelio para impulsar la narración a un ritmo vertiginoso. Marca la inmediatez de la acción divina: el Espíritu desciende sobre Jesús al instante en su bautismo (Mt 3:16), los discípulos dejan sus redes de inmediato al ser llamados (Mt 4:20) y la lepra se retira en el momento en que Jesús habla (Mt 8:3). La palabra comunica no solo rapidez sino la cualidad decisiva e irresistible de los acontecimientos impulsados por la autoridad divina. Las traducciones convergen estrechamente: español «inmediatamente», francés «aussitôt», alemán «sogleich».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2114', 'spa', 'Tener buen ánimo, animarse; estar alegre o cobrar valor', 'Este verbo significa tener buen ánimo, cobrar valor o mantener un espíritu alegre. Aparece en contextos de aliento ante la adversidad. Pablo lo emplea dos veces a bordo de un barco azotado por la tempestad para infundir ánimo a los marineros atemorizados (Hechos 27:22, 25), y Santiago lo usa para describir a quienes deben cantar alabanzas cuando están contentos (Santiago 5:13). El término enfatiza la disposición interior: mantener el buen ánimo o expresar gozo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2117', 'spa', 'Recto, directo o moralmente íntegro; se usa de caminos allanados y de una conducta justa.', 'Adjetivo que significa físicamente recto o moralmente justo, εὐθύς es el antónimo de σκολιός (''torcido''). Su uso más memorable en el Nuevo Testamento recoge Isaías 40:3 — ''enderezad los caminos del Señor'' — y aparece en los tres sinópticos (Mt 3:3; Mr 1:3; Lc 3:4–5) como el pregón de Juan el Bautista. Pedro le dice a Simón el Mago que su corazón ''no es recto'' delante de Dios (Hch 8:21), y el ''camino recto'' funciona como norma moral que Balaam abandonó (2 P 2:15). El término fusiona de manera natural la imagen geométrica con la ética.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2118', 'spa', 'Rectitud, integridad moral; cualidad de ser recto en carácter y conducta', 'Aunque este sustantivo puede describir la rectitud física literal, la Septuaginta y el Nuevo Testamento lo emplean para la rectitud moral: la cualidad de ser íntegro en carácter y acción. En Hebreos 1:8, aparece en una cita del Salmo 45: «el cetro de rectitud es el cetro de tu reino». Esta justicia caracteriza el gobierno mismo de Dios y al Mesías que encarna la justicia divina. No se trata de mera corrección formal, sino de una integridad profunda que define el reinado celestial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2119', 'spa', 'Tener oportunidad, disponer de tiempo; contar con un momento propicio para algo', 'Este verbo significa tener oportunidad, tiempo libre o un momento favorable para realizar algo. Puede indicar disponer de un instante conveniente, encontrar tiempo o disfrutar de circunstancias propicias. En el Nuevo Testamento aparece cuando el tiempo o la oportunidad está presente o ausente: los discípulos demasiado ocupados para comer (Marcos 6:31), los atenienses dedicando su tiempo a debatir ideas (Hechos 17:21) y Apolos sin oportunidad de visitar Corinto (1 Corintios 16:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2123', 'spa', 'Más fácil (comparativo de εὔκοπος); usado en comparaciones de dificultad, especialmente en los desafíos retóricos de Jesús.', 'Es la forma comparativa de εὔκοπος (''fácil''), y aparece casi exclusivamente en las incisivas preguntas retóricas de Jesús. Cuando pregunta ''¿Qué es más fácil: decir tus pecados te son perdonados, o decir levántate y anda?'' (Mt 9:5; Mr 2:9; Lc 5:23), el término plantea una paradoja deliberada sobre la autoridad divina. También aparece en el célebre dicho del camello por el ojo de la aguja (Mt 19:24; Mr 10:25; Lc 18:25). En todos los casos el comparativo sirve para enmarcar lo humanamente imposible frente al poder soberano de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2125', 'spa', 'Actuar con cautela reverente, mostrar temor piadoso; tomar en serio una advertencia divina con reverencia', 'Este verbo abarca la cautela reverente: tomar algo con la seriedad suficiente para actuar de manera cuidadosa y apropiada. En Hebreos 11:7, describe la respuesta de Noé a la advertencia divina sobre el diluvio venidero: «con temor reverente preparó el arca». La palabra no sugiere ni terror paralizante ni indiferencia casual, sino la respuesta seria y activa que corresponde cuando Dios habla: acoger la advertencia divina con todo su peso y responder en obediencia concreta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2126', 'spa', 'devoto, reverente, piadoso; quien asume con esmero sus obligaciones sagradas ante Dios', 'Compuesto de εὖ (''bien'') y λαβεῖν (''tomar, asir''), este adjetivo describía originalmente a alguien que procede con cautela y prudencia. En la Septuaginta y el Nuevo Testamento, su sentido se desplazó decididamente hacia la reverencia religiosa: una persona que ''toma con cuidado'' sus deberes ante Dios. Simeón encarna esta cualidad en Lucas 2:25 mientras aguarda al Mesías con fe paciente. Los judíos devotos reunidos en Pentecostés (Hch 2:5), quienes sepultaron a Esteban (Hch 8:2) y Ananías, elogiado por la comunidad judía (Hch 22:12), comparten esta piedad sincera que distingue al εὐλαβής de la mera precaución.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2127', 'spa', 'Bendecir, pronunciar una bendicion; ser bendecido o declarado bienaventurado; alabar o dar gracias a Dios.', 'Bendecir, pronunciar una bendicion; ser bendecido o declarado bienaventurado; alabar o dar gracias a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2128', 'spa', 'Bendito, digno de alabanza; adjetivo verbal reservado casi exclusivamente para Dios como objeto de bendición.', 'Este adjetivo verbal derivado de εὐλογέω (''bendecir'') pertenece a un registro litúrgico elevado y se emplea en el Nuevo Testamento casi exclusivamente referido a Dios o a Cristo. Aparece en fórmulas doxológicas como ''Bendito sea el Dios y Padre de nuestro Señor Jesucristo'' (2 Co 1:3; Ef 1:3; 1 P 1:3) y en la pregunta del sumo sacerdote sobre si Jesús es ''el Cristo, el Hijo del Bendito'' (Mr 14:61). La declaración de Pablo de que Cristo es ''Dios sobre todas las cosas, bendito por los siglos'' (Ro 9:5) eleva el término a una afirmación cristológica. Es una palabra que pertenece al ámbito de la adoración, no al habla cotidiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2129', 'spa', 'Bendición: ya sea un pronunciamiento divino de favor, un don concreto de generosidad o (raramente) adulación engañosa disfrazada de elogio. Literalmen', 'Bendición: ya sea un pronunciamiento divino de favor, un don concreto de generosidad o (raramente) adulación engañosa disfrazada de elogio. Literalmente «buena palabra» (εὐ + λόγος), este sustantivo abarca un amplio arco en las cartas de Pablo. En su sentido más pleno nombra las bendiciones espirituales que Dios otorga en Cristo (Efesios 1:3), la «copa de bendición» en la Cena del Señor (1 Corintios 10:16) y la bendición prometida de Abraham extendida a todas las naciones (Gálatas 3:14). Pablo también lo usa concretamente de un don monetario generoso: lo que los corintios prometieron debe estar listo como «bendición» (generosidad), no como extorsión (2 Corintios 9:5-6). En un llamativo contrauso, Romanos 16:18 advierte que los falsos maestros usan εὐλογία —palabras suaves y halagadoras— para engañar a los ingenuos, invirtiendo la valencia positiva de la palabra en arma de manipulación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2130', 'spa', 'Generoso, dispuesto a compartir; liberal en dar y distribuir recursos a otros', 'Este adjetivo describe la cualidad de estar prontamente dispuesto a compartir lo que uno posee con los demás. Pablo lo usa en 1 Timoteo 6:18, instruyendo a los ricos «que sean generosos y prontos a compartir». La palabra no capta un cumplimiento a regañadientes de expectativas caritativas, sino una disposición alegre a distribuir recursos, viendo las posesiones como destinadas a compartirse en lugar de acumularse. Es la generosidad como rasgo de carácter, no como obligación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2131', 'spa', 'Eunice, nombre propio que significa ''buena victoria''; madre de Timoteo', 'Eunice fue la madre de Timoteo, una creyente judía casada con un hombre griego (Hechos 16:1). Pablo elogia su fe sincera en 2 Timoteo 1:5, señalando que esa fe habitó primero en su abuela Loida, luego en Eunice y finalmente en Timoteo, formando un hermoso testimonio de tres generaciones. A pesar de los desafíos de un matrimonio mixto en aquel contexto cultural, Eunice logró transmitir la fe a su hijo, quien llegó a ser el colaborador más confiable de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2132', 'spa', 'Estar bien dispuesto, mostrar buena voluntad; resolver asuntos pacíficamente', 'Este verbo indica estar favorablemente inclinado hacia alguien, mantener relaciones cordiales y buscar una resolución pacífica. Jesús lo emplea en Mateo 5:25: ''Ponte de acuerdo pronto con tu adversario mientras vas con él por el camino.'' La forma participial puede significar ''reconciliarse'' o ''mostrarse conciliador''; en ambos casos, la sabiduría consiste en resolver las disputas a tiempo antes de que escalen a un juicio formal donde los resultados se vuelven impredecibles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2133', 'spa', 'Buena voluntad, disposición favorable; bondad y benevolencia hacia los demás', 'Este sustantivo capta la cualidad de estar favorablemente inclinado hacia alguien, marcada por la bondad, la benevolencia y una intención positiva. En Efesios 6:7, Pablo instruye a los siervos a servir ''con buena voluntad, como al Señor y no a los hombres.'' La palabra apunta a la actitud interior que transforma el mero cumplimiento en un servicio alegre: hacer el trabajo de corazón porque en última instancia se está sirviendo a Cristo, no solo a amos humanos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2135', 'spa', 'Eunuco; varón castrado, frecuentemente oficial de la corte o chambelán; también se usa figuradamente para el celibato voluntario.', 'Derivado de εὐνή (''lecho'') + ἔχω (''tener''), el término originalmente describía al guardián del dormitorio real: un hombre castrado al que se confiaba el acceso a las mujeres de la corte. En Hechos 8:27–39, el eunuco etíope es un alto funcionario del tesoro de la reina Candace, y su encuentro con Felipe se convierte en un relato emblemático del evangelio cruzando fronteras étnicas y sociales. En Mateo 19:12, Jesús amplía el término a tres categorías: los que nacieron eunucos, los que fueron hechos así por otros, y los que ''se hicieron eunucos a sí mismos por causa del reino de los cielos'', un uso figurado referido al celibato voluntario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2136', 'spa', 'Evodia, nombre propio que posiblemente significa ''buen viaje'' o ''prosperidad''; creyente en Filipos', 'Evodia fue una mujer prominente en la iglesia de Filipos a quien Pablo insta a reconciliarse con Síntique en Filipenses 4:2. Estas dos mujeres habían ''combatido juntamente'' con Pablo en el evangelio (4:3), lo que sugiere una colaboración ministerial significativa. Su desacuerdo público preocupó a Pablo lo suficiente como para mencionarlas por nombre en su carta, mostrando tanto la importancia de su labor como el daño que su conflicto representaba para la unidad de la iglesia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2137', 'spa', 'prosperar, tener éxito, hacer buen viaje; recibir prosperidad concedida por Dios', 'Con el sentido original de ''ayudar a alguien en su camino'', este verbo amplió su alcance en el uso bíblico para abarcar toda clase de prosperidad o éxito, frecuentemente entendidos como concedidos por Dios. La oración de Pablo por un viaje seguro a Roma (Ro 1:10) conserva el sentido de travesía, mientras que su instrucción de apartar fondos ''según haya prosperado'' (1 Co 16:2) se desplaza al bienestar económico. En 3 Juan 1:2 aparece dos veces, cubriendo tanto la prosperidad material como la salud espiritual. El español ''prosperar'' captura bien toda la amplitud semántica del término griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2138', 'spa', 'Dispuesto a obedecer, dócil; fácilmente persuadido hacia el bien, razonable', 'Este adjetivo describe la cualidad de estar dispuesto a escuchar razones y responder positivamente al buen consejo. Santiago lo utiliza para caracterizar la sabiduría celestial: ''la sabiduría que es de lo alto es primeramente pura, después pacífica, amable, benigna, dócil'' (Santiago 3:17). Esta apertura a la razón contrasta con la sabiduría terrenal obstinada y facciosa: distingue a quienes pueden ser interpelados, quienes escuchan y se ajustan cuando se les muestra un camino mejor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2139', 'spa', 'Que enreda fácilmente, que se ciñe estrechamente; aquello que se adhiere e impide el avance', 'Este raro adjetivo describe algo que se enrolla con facilidad alrededor de una persona y le estorba el movimiento, como una vestimenta que se engancha o enreda las piernas durante una carrera. El autor de Hebreos lo emplea para hablar del «pecado que nos asedia» (12:1), exhortando a los creyentes a «despojarse de todo peso» y de ese pecado que enreda, a fin de correr sin estorbos la carrera de la fe. La imagen evoca a un atleta que se despoja de todo lo que pueda frenar su máximo rendimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2140', 'spa', 'Hacer el bien, beneficencia; la práctica de realizar actos provechosos en favor de otros', 'Este sustantivo designa la actividad de hacer el bien a los demás: actos concretos de bondad y beneficio. En Hebreos 13:16 aparece junto al compartir: «No os olvidéis de hacer el bien y de la ayuda mutua, porque de tales sacrificios se agrada Dios.» La palabra subraya no las meras buenas intenciones, sino las acciones benéficas reales que cuestan algo y ayudan a otros, las cuales Dios recibe como auténtica adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2141', 'spa', 'Prosperar, estar bien provisto; disponer de recursos y medios', 'Este verbo describe el tener recursos suficientes o abundantes, hallarse en circunstancias favorables, prosperar material o económicamente. Lucas lo emplea en Hechos 11:29, cuando los discípulos de Antioquía decidieron enviar ayuda a los creyentes de Judea: «cada uno conforme a sus posibilidades» (literalmente, «según prosperara cada uno»). El vocablo indica disponer de medios para compartir, no una mera subsistencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2142', 'spa', 'Prosperidad, abundancia; circunstancias favorables y recursos abundantes', 'Este sustantivo indica recursos abundantes, prosperidad o circunstancias materiales favorables. En Hechos 19:25, Demetrio el platero reúne a sus compañeros artesanos contra Pablo señalando que «de este oficio obtenemos nuestra prosperidad», refiriéndose al lucrativo comercio de ídolos que el evangelio amenazaba. El término capta el bienestar material, el florecimiento económico que puede convertirse tanto en bendición como en ídolo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2143', 'spa', 'Hermosura, belleza exterior; apariencia atractiva o forma elegante', 'Este sustantivo describe la belleza exterior, la apariencia atractiva o la forma elegante. Santiago lo emplea en su ilustración sobre la fugacidad de la vida: el rico se marchitará «en medio de sus afanes, como la flor de la hierba... su hermosura perece» (1:11). Así como las flores silvestres exhiben una belleza deslumbrante pero efímera antes de que el sol abrasador las marchite, la gloria y el atractivo humanos resultan pasajeros cuando llega el calor de la eternidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2144', 'spa', 'Aceptable, bien recibido, agradable; describe ofrendas, servicio o acciones que hallan favorable acogida ante Dios.', 'Adjetivo compuesto que significa ''bien recibido'' o ''plenamente aceptable'', empleado exclusivamente en contextos de aprobación divina. Pablo describe a los gentiles como una ofrenda ''aceptable'' a Dios mediante la obra santificadora del Espíritu (Rom 15:16) y ruega que su servicio en Jerusalén resulte aceptable a los santos (Rom 15:31). El término evoca el lenguaje veterotestamentario del sacrificio agradable. En 2 Corintios 6:2, Pablo cita a Isaías para declarar que ''ahora es el tiempo aceptable'' de salvación. Las traducciones en diversas lenguas convergen en la idea de recepción favorable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2145', 'spa', 'Atención constante, servicio devoto; disponibilidad persistente y enfoque sin distracciones', 'Este raro adjetivo compuesto describe una asistencia persistente y sin distracciones, o una devoción completa hacia alguien o algo. Pablo lo emplea en 1 Corintios 7:35 al hablar del estado de soltería: este promueve una «devoción sin reservas al Señor» (literalmente, «asistencia constante»). La palabra sugiere estar plenamente disponible, atento y concentrado, sin las lealtades divididas que el matrimonio necesariamente conlleva. No implica que el matrimonio sea malo, sino que la soltería ofrece una ventaja práctica para el servicio dedicado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2146', 'spa', 'Hacer buena apariencia, presentar una imagen atractiva; lucir bien exteriormente', 'Este verbo significa hacer una exhibición externa atractiva o presentar una buena apariencia, a menudo con la implicación de que lo exterior enmascara la realidad. Pablo lo usa en Gálatas 6:12 para criticar a los judaizantes: «los que quieren causar buena impresión en la carne» obligando a los gentiles a circuncidarse. Su motivación no era convicción teológica, sino evitar la persecución, luciendo respetables ante los observadores mientras esquivaban la ofensa de la cruz. El contraste entre lo aparente y lo real es central en este término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2147', 'spa', 'Hallar, encontrar, descubrir; en pasiva: ser hallado, resultar ser, ser revelado.', 'Un verbo de percepción y encuentro en el corazón de muchas narrativas neotestamentarias. Ya sea un pastor hallando la oveja perdida, un mercader descubriendo una perla de gran precio (Mt 13:44-46) o María siendo hallada encinta (Mt 1:18), εὑρίσκω tiende un puente entre la búsqueda deliberada y el descubrimiento inesperado. La voz pasiva frecuentemente porta peso teológico: ser ''hallado'' en Cristo o ser ''hallado'' fiel. Un tercer matiz apunta a la obtención o adquisición mediante esfuerzo, como cuando Cristo ''obtuvo'' redención eterna (Heb 9:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2148', 'spa', 'Euroaquilón o Euroclidón, un violento viento del noreste en el Mediterráneo; viento tempestuoso', 'Este término designa un feroz viento del noreste en el Mediterráneo, que combina elementos griegos y latinos (probablemente «euro-» del griego para viento del este y «aquilo» del latín para viento del norte). En Hechos 27:14, este «noreste» golpea el barco de Pablo que navegaba hacia Roma, desviándolo de su rumbo y casi destruyendo la embarcación. Los marineros de la antigüedad temían particularmente este viento por su violencia y por la forma en que podía sorprender a los navíos de manera inesperada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2149', 'spa', 'Espacioso, ancho, amplio; que tiene mucho espacio o anchura', 'Este adjetivo describe amplitud física o espaciosidad: algo ancho, holgado o extenso. Jesús lo emplea en el Sermón del Monte para describir el camino que lleva a la perdición: «ancha es la puerta y espacioso el camino que lleva a la destrucción» (Mateo 7:13). El camino amplio y espacioso no requiere esfuerzo alguno para transitarlo: acomoda toda inclinación, lo cual lo hace trágicamente popular mientras conduce a la ruina. La amplitud que parece tan atractiva resulta ser mortal, mientras que el sendero estrecho y angosto lleva a la vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2150', 'spa', 'Εὐσέβεια denota una vida orientada hacia Dios tanto en reverencia interior como en conducta exterior. Es la virtud distintiva de las Epístolas Pastora', 'Εὐσέβεια denota una vida orientada hacia Dios tanto en reverencia interior como en conducta exterior. Es la virtud distintiva de las Epístolas Pastorales, donde Pablo exhorta a Timoteo a ''ejercitarse para la piedad'' (1 Ti 4:7) y la nombra entre las virtudes que se deben perseguir (1 Ti 6:11). El ''misterio de la piedad'' en 1 Timoteo 3:16 ancla el concepto en la encarnación misma. Segunda de Pedro añade la εὐσέβεια a la escalera del crecimiento espiritual junto con el dominio propio, la perseverancia y el amor (2 P 1:6-7). La palabra une la disposición interior y la práctica visible — no un mero sentimiento religioso, sino todo un patrón de vida que honra a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2152', 'spa', 'Devoto, piadoso, reverente; caracterizado por la devoción religiosa y el temor de Dios', 'Este adjetivo describe a quienes se distinguen por su piedad, devoción religiosa y reverencia hacia Dios. En el griego clásico enfatizaba el cumplimiento de deberes sagrados y el respeto debido a lo divino. En el Nuevo Testamento caracteriza a personas reconocidas por una piedad genuina: Cornelio y su familia (Hechos 10:2, 7) y los fieles a quienes Dios libra de la prueba (2 Pedro 2:9). El término señala una devoción activa y visible, no una mera profesión de fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2154', 'spa', 'Claro, inteligible, fácilmente comprensible; marcado por claridad y distinción', 'Este adjetivo describe algo fácilmente conocido o comprendido: claro, inteligible, distinto. Pablo lo usa en 1 Corintios 14:9 al discutir el hablar en lenguas durante el culto: «Si no pronunciáis un discurso inteligible, ¿cómo se sabrá lo que decís?» La palabra enfatiza la claridad en la comunicación, esa cualidad que hace posible la comprensión, exactamente lo que las lenguas sin interpretación carecen en la adoración pública. El punto de Pablo es pastoral: el culto debe edificar al cuerpo mediante una comunicación clara y comprensible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2156', 'spa', 'Decorosamente, dignamente, con decoro; de manera apropiada conforme al buen orden y la decencia', 'Este adverbio significa de manera decorosa, digna o apropiada según las normas de conducta aceptadas. Deriva de εὐσχήμων (presentable, honorable) y enfatiza un comportamiento decente y adecuado. Pablo lo emplea tres veces para exhortar a una conducta cristiana apropiada: en la vida pública (Romanos 13:13), en el culto de la iglesia (1 Corintios 14:40) y en el trato cotidiano (1 Tesalonicenses 4:12). El término subraya el decoro visible y el buen orden.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2157', 'spa', 'Decoro, dignidad, apariencia decorosa; la cualidad de ser presentable o respetable en aspecto', 'Este sustantivo designa la cualidad de ser presentable, respetable o decoroso en apariencia. Pablo lo emplea en 1 Corintios 12:23 al hablar del cuerpo de Cristo: otorgamos mayor honor a las partes menos presentables, y nuestras partes menos decorosas reciben un trato más modesto. La palabra apunta a la propiedad social y la apariencia digna que ciertas partes del cuerpo carecen de forma natural, pero que reciben mediante el cuidado y la vestimenta que les damos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2158', 'spa', 'Respetable, honorable, prominente; describe personas de posición social distinguida o partes del cuerpo que merecen trato digno.', 'Literalmente ''de buena forma o porte'', este adjetivo describe a personas socialmente prominentes, moralmente respetables o físicamente presentables. Marcos lo usa para José de Arimatea, miembro ''prominente'' del concilio que se atrevió a pedir el cuerpo de Jesús a Pilato (Mar 15:43). En Hechos, describe a las mujeres y hombres influyentes de Tesalónica y Berea que se opusieron al evangelio o lo abrazaron (Hch 13:50; 17:12). Pablo reutiliza el término en 1 Corintios 12:24 para referirse a las partes ''decorosas'' del cuerpo que no necesitan honor adicional, contrastándolas con los miembros menos presentables que Dios ha dignificado especialmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2160', 'spa', 'Bufonada, chiste grosero, humor vulgar o chabacano; jocosidad degradante', 'Este sustantivo originalmente significaba ingenio ágil o chiste ingenioso, pero llegó a denotar humor grosero, bromas vulgares o bufonería. Pablo lo enumera en Efesios 5:4 entre las formas impropias de hablar: ''Ni obscenidades, ni necedades, ni groserías, que no convienen, sino más bien acciones de gracias.'' La palabra señala un tipo de humor que degrada, trivializa las cosas sagradas o se deleita en lo chabacano en lugar de edificar a los demás.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2161', 'spa', 'Eutico, nombre propio que significa ''afortunado''; un joven en Troas', 'Eutico fue un joven en Troas que se cayó desde una ventana del tercer piso durante un extenso sermón de Pablo y fue recogido muerto, pero Pablo lo devolvió a la vida (Hechos 20:9-12). Su nombre significa irónicamente ''afortunado'' o ''dichoso'': aunque quedarse dormido durante un sermón y desplomarse hasta la muerte parecía ciertamente desafortunado, la intervención de Pablo hizo que el nombre resultara proféticamente acertado. El episodio muestra tanto la preocupación pastoral de Pablo como su poder apostólico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2162', 'spa', 'Buena fama, reputación favorable; honor y elogio de parte de otros', 'Este sustantivo denota el hablar favorable acerca de alguien, la buena reputación o el informe elogioso. Pablo lo emplea en 2 Corintios 6:8 para describir los contrastes del ministerio apostólico: ''por honra y deshonra, por mala y buena fama'', a veces elogiados, a veces calumniados, pero fieles sin importar lo que otros digan. La palabra subraya la reputación en boca de los demás, el informe favorable que trae reconocimiento y honor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2163', 'spa', 'Digno de elogio, loable, honorable; merecedor de buen informe o aprobación', 'Este adjetivo describe aquello que es digno de alabanza o encomio, merecedor de un informe favorable. Pablo lo usa en su célebre lista de virtudes en Filipenses 4:8: ''todo lo que es verdadero, honesto, justo, puro, amable, de buen nombre, en esto pensad.'' La palabra indica lo que merece aprobación y debe ocupar los pensamientos del creyente: las cosas excelentes dignas de meditación en lugar de asuntos triviales o degradantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2164', 'spa', 'Producir abundantemente, dar fruto con generosidad; rendir cosecha copiosa', 'Este verbo describe la acción de producir bien o abundantemente, dar fruto con éxito y generosidad. Jesús lo emplea en la parábola del rico insensato, cuya tierra «produjo mucho» (Lucas 12:16), rindiendo tal abundancia que no tenía dónde almacenarla. La palabra enfatiza una producción exitosa y generosa: la tierra haciendo exactamente lo que debe hacer, dando fruto con riqueza. Irónicamente, en la parábola de Jesús, este éxito agrícola conduce al desastre espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2165', 'spa', 'Construido a partir de εὖ (''bien'') y φρήν (''mente''), este verbo capta la plenitud de la alegría — desde el gozo interior tranquilo hasta la celebració', 'Construido a partir de εὖ (''bien'') y φρήν (''mente''), este verbo capta la plenitud de la alegría — desde el gozo interior tranquilo hasta la celebración exuberante. Su forma media/pasiva domina en el Nuevo Testamento, apareciendo prominentemente en las parábolas de recuperación de Jesús: el padre ordena ''hagamos fiesta'' cuando el pródigo regresa (Lc 15:23-24, 32), y el hermano mayor se queja de que nunca se le dio un cabrito para ''festejar'' con sus amigos (Lc 15:29). Apocalipsis usa el verbo tanto en la adoración celestial (''¡Regocíjate sobre ella, oh cielo!'' Ap 18:20) como en la corrupción terrenal (Ap 11:10; 18:7). La única aparición activa-transitiva en 2 Corintios 2:2 — ''¿quién me alegrará?'' — revela la ternura pastoral de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2168', 'spa', 'Dar gracias, expresar gratitud; raramente en voz pasiva: ser agradecido o recibido con accion de gracias.', 'Dar gracias, expresar gratitud; raramente en voz pasiva: ser agradecido o recibido con accion de gracias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2169', 'spa', 'Εὐχαριστία — la palabra de la que deriva ''Eucaristía'' — denota el acto de expresar gratitud a Dios. Pablo trata la acción de gracias como algo fundame', 'Εὐχαριστία — la palabra de la que deriva ''Eucaristía'' — denota el acto de expresar gratitud a Dios. Pablo trata la acción de gracias como algo fundamental en la vida cristiana: debe acompañar toda oración (Fil 4:6; Col 4:2), desbordar de la experiencia comunitaria de la gracia (2 Co 4:15; 9:11-12) y caracterizar todo discurso en lugar de la grosería (Ef 5:4). En 1 Corintios 14:16 Pablo insiste en que la acción de gracias corporativa debe ser inteligible para que otros puedan decir ''Amén''. Las cartas pastorales la enmarcan como la respuesta apropiada a la buena creación de Dios (1 Ti 4:3-4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2170', 'spa', 'Agradecido, lleno de gratitud; caracterizado por el reconocimiento y la acción de gracias', 'Este adjetivo describe la cualidad de ser agradecido, de expresar gratitud o de estar marcado por el reconocimiento. Pablo instruye a los colosenses a «ser agradecidos» (Colosenses 3:15), haciendo de la gratitud una característica definitoria de la comunidad cristiana. La palabra no indica una gratitud ocasional, sino una disposición permanente de aprecio reconocido por los dones y la gracia de Dios, lo opuesto al espíritu quejumbroso y de autosuficiencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2171', 'spa', 'voto, oración; promesa solemne o petición dirigida a Dios', 'Este sustantivo designa un voto u oración, en particular una promesa solemne hecha ante Dios. En el uso clásico predominaba la idea de un compromiso que debía cumplirse. En el Nuevo Testamento aparece en contextos de votos judíos: la participación de Pablo en un voto nazareo (Hechos 18:18), el consejo sobre hombres bajo voto (Hechos 21:23) y la oración de fe por los enfermos (Santiago 5:15). El término señala un compromiso religioso serio o una petición ferviente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2172', 'spa', 'Orar, dirigir una petición a Dios; desear intensamente, incluso de modo hipotético o irrealizable.', 'El verbo εὔχομαι posee una doble vida heredada del griego clásico: significa tanto orar —dirigirse a Dios con peticiones o intercesión— como desear ardientemente. En el uso clásico ambos sentidos estaban entrelazados, pues orar y desear implican proyectar un anhelo hacia afuera. El Nuevo Testamento conserva ambos matices. Pablo ora por la restauración de los corintios (2 Co 13:9), los ancianos oran por los enfermos (Stg 5:16) y los marineros claman por la luz del día en la tormenta (Hch 27:29). Sin embargo, en Romanos 9:3 Pablo emplea el imperfecto ηὐχόμην para expresar un deseo hipotético asombroso: que él mismo fuera anatema por amor a Israel, un anhelo tan contrario a la realidad que transforma la palabra de oración en puro deseo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2173', 'spa', 'útil, provechoso; apto y beneficioso para el propósito previsto', 'Este adjetivo significa útil, provechoso o beneficioso para una persona o propósito determinado. En el uso clásico destacaba la aptitud para el servicio. En el Nuevo Testamento Pablo lo emplea tres veces refiriéndose a la utilidad de personas en el ministerio: vasos útiles para el dueño de la casa (2 Timoteo 2:21), Onésimo que volvió a ser provechoso (Filemón 11) y Marcos como útil para el ministerio (2 Timoteo 4:11). El término subraya el valor práctico del servicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2174', 'spa', 'Ser animado, cobrar ánimo; tener el espíritu fortalecido y reconfortado', 'Este verbo significa cobrar buen ánimo, sentir el espíritu levantado o experimentar aliento y consuelo. Pablo lo usa en Filipenses 2:19 al expresar su esperanza de enviar a Timoteo: «para que yo también me anime al conocer vuestra condición». La palabra indica que el alma o el espíritu se fortalece, que uno se reconforta con buenas noticias, que experimenta el consuelo que proviene de informes positivos acerca de los seres queridos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2175', 'spa', 'fragancia, aroma agradable; olor grato, especialmente el de un sacrificio', 'Este sustantivo designa un aroma agradable o fragancia, especialmente el olor grato de los sacrificios que ascienden a Dios. En el Antiguo Testamento las ofrendas se describen como ''aroma grato al Señor''. Pablo emplea esta imaginería sacrificial de forma metafórica: los cristianos como aroma de Cristo (2 Corintios 2:15), el sacrificio de Cristo como ofrenda fragante (Efesios 5:2) y la ofrenda de los filipenses como sacrificio agradable a Dios (Filipenses 4:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2176', 'spa', 'Izquierdo, del lado izquierdo; termino eufemistico que originalmente significaba ''de buen nombre'', usado en el NT solo para posicion espacial.', 'Euonymos es uno de los grandes eufemismos del griego. Literalmente significa ''de buen nombre'', y se usaba para evitar el mal augurio de decir ''izquierdo'', ya que ese lado se consideraba de mala suerte. Para la epoca del NT, el origen eufemistico se habia desvanecido y simplemente significaba ''izquierdo''. Sus nueve apariciones se concentran en la peticion de asientos de honor junto a Jesus (Mt 20:21,23; Mc 10:37,40), la separacion en el juicio final (Mt 25:33,41) y la posicion de los crucificados junto a Jesus (Mt 27:38; Mc 15:27).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2177', 'spa', 'Saltar encima, abalanzarse sobre; atacar lanzándose violentamente contra alguien', 'Este verbo describe la acción de saltar o abalanzarse sobre alguien o algo, generalmente con intención hostil: atacar lanzándose sobre un adversario. Lucas lo emplea en Hechos 19:16 al describir al endemoniado en Éfeso que «saltó sobre» los siete hijos de Esceva cuando estos intentaron un exorcismo, dominándolos a todos. La palabra enfatiza un asalto repentino y violento, el salto agresivo de ataque en lugar de una aproximación gradual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2178', 'spa', 'De una vez para siempre, en una sola ocasión; denota un acto único y decisivo con efecto permanente e irrepetible.', 'Adverbio enfático que significa ''de una vez para siempre'', subrayando que una acción se realiza una sola vez con efecto permanente e irreversible. Posee gran peso teológico en Hebreos, donde contrasta el sacrificio de Cristo con las ofrendas levíticas repetidas: él se ofreció a sí mismo ''de una vez para siempre'' (Heb 7:27; 9:12; 10:10), asegurando la redención eterna en un solo acto. Pablo lo emplea en Romanos 6:10 para declarar que Cristo ''murió al pecado de una vez para siempre''. El único uso no sacrificial describe a los quinientos testigos que vieron al Cristo resucitado ''de una vez'' (1 Cor 15:6). La expresión española ''de una vez para siempre'' capta vívidamente esa finalidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2179', 'spa', 'efesino; perteneciente a o procedente de la ciudad de Éfeso', 'Adjetivo que significa «de Éfeso» o «efesino», referente a la prominente ciudad de Asia Menor que albergaba el templo de Artemisa y posteriormente una importante comunidad cristiana. La tradición textual de Apocalipsis 2:1 muestra variación entre esta forma adjetival y la frase preposicional «en Éfeso». Pablo pasó un tiempo prolongado en Éfeso, y su carta a los Efesios se dirige a los creyentes allí. El término identifica tanto a los residentes como las características asociadas con este significativo centro del cristianismo primitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2180', 'spa', 'Efesio; perteneciente o relativo a Éfeso, la principal ciudad de la provincia romana de Asia.', 'Adjetivo gentilicio que designa el origen o la vinculación con la ciudad de Éfeso, una de las ciudades más prominentes de la provincia romana de Asia. En el Nuevo Testamento aparece exclusivamente en Hechos, donde los efesios defienden con fervor su identidad cívica y el culto a Artemisa. Las cinco apariciones se concentran en Hch 19–21: el grito de los artesanos ''¡Grande es Artemisa de los efesios!'' (Hch 19:28, 34), el secretario de la ciudad dirigiéndose a la multitud como efesios (Hch 19:35), y la acusación de que Pablo introdujo a Trófimo el efesio en el templo (Hch 21:29).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2181', 'spa', 'Éfeso: ciudad principal de la provincia romana de Asia, centro de la misión cristiana primitiva y del culto a Artemisa. Éfeso era la ciudad principal ', 'Éfeso: ciudad principal de la provincia romana de Asia, centro de la misión cristiana primitiva y del culto a Artemisa. Éfeso era la ciudad principal del Asia proconsular, un bullicioso puerto y centro comercial famoso por su templo de Artemisa, una de las siete maravillas del mundo antiguo. En Hechos, Pablo visita Éfeso en su segundo viaje (18:19-21) y luego pasa más de dos años allí en el tercero (19:1-41), desencadenando un motín entre los plateros que temían por su comercio de santuarios de Artemisa. La ciudad se convirtió en un centro principal de la misión paulina: Pablo escribió 1 Corintios desde Éfeso (1 Corintios 16:8), dirigió una carta a la iglesia efesia (Efesios 1:1), dejó a Timoteo allí para supervisar la comunidad (1 Timoteo 1:3), y aparece como la primera de las siete iglesias en Apocalipsis (Apocalipsis 2:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2182', 'spa', 'Inventores, ideadores; quienes conciben y crean cosas nuevas, especialmente maquinaciones malvadas', 'Este sustantivo describe a quienes inventan, idean o maquinan cosas, particularmente en contextos negativos: aquellos que conciben nuevas formas de maldad. Pablo lo usa en Romanos 1:30 en su catálogo de la humanidad depravada: son «inventores de males». La palabra sugiere no solo la práctica de maldades ya existentes, sino la innovación creativa en el pecado, ideando formas inéditas de rebelión y corrupción que van más allá de lo que la tradición ya ofrecía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2184', 'spa', 'Diario, cotidiano; que pertenece al día o satisface las necesidades de cada jornada', 'Este adjetivo significa ''del día'' o ''diario'', y describe aquello que pertenece a cada jornada, se repite cotidianamente o cubre las necesidades diarias. Santiago lo emplea al presentar el caso hipotético de alguien que carece del ''alimento diario'' (Santiago 2:15), es decir, el sustento básico que se necesita cada día. La palabra subraya el carácter cotidiano y recurrente de algo: lo que se necesita o se experimenta día tras día.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2186', 'spa', 'Estar al lado, presentarse de repente, estar presente o inminente; también apremiar con urgencia o atacar con intención hostil', 'Estar al lado, presentarse de repente, estar presente o inminente; también apremiar con urgencia o atacar con intención hostil');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2187', 'spa', 'Efraín, nombre de lugar; pueblo cercano a Jerusalén donde Jesús se retiró', 'Efraín era un pueblo en el desierto cercano a Jerusalén, adonde Jesús se retiró con sus discípulos tras resucitar a Lázaro (Juan 11:54). Su ubicación exacta es debatida, pero ofrecía un refugio apartado mientras el Sanedrín tramaba activamente la muerte de Jesús. El nombre evoca al hijo del patriarca y a la tribu del norte de Israel, pero se trata de un pueblo judeano distinto, cuya relevancia bíblica radica únicamente en haber servido como escondite temporal de Jesús antes de su última Pascua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2188', 'spa', 'Efatá, mandato arameo que significa ''sé abierto''; palabra de sanación pronunciada por Jesús', 'Esta es la palabra aramea que Jesús pronunció al sanar a un sordo con impedimento del habla en Marcos 7:34. Mirando al cielo y suspirando profundamente, Jesús tocó los oídos y la lengua del hombre y dijo ''Efatá'', es decir, ''sé abierto''. Marcos conserva el arameo original y lo traduce para sus lectores griegos, siendo una de varias ocasiones en que la lengua materna de Jesús irrumpe en la narrativa griega, añadiendo intimidad y autenticidad histórica al relato de la sanación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2189', 'spa', 'Enemistad, hostilidad o antagonismo profundo y arraigado entre partes, ya sea personal, cósmico o espiritual.', 'Sustantivo abstracto que denota una hostilidad asentada o un antagonismo profundo: no una disputa pasajera, sino una fractura honda entre partes opuestas. Pablo la identifica como «obra de la carne» junto con los celos y las contiendas (Gá 5:20), pero también la emplea teológicamente para describir la hostilidad cósmica entre la humanidad pecadora y Dios (Ro 8:7) y el muro divisorio de enemistad entre judío y gentil que Cristo abolió (Ef 2:14-16). Lucas registra que Herodes y Pilato habían estado enemistados antes de reconciliarse durante el juicio de Jesús (Lc 23:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2190', 'spa', 'Enemigo, adversario hostil; aquel que se opone personal, nacional o espiritualmente.', 'Enemigo, adversario hostil; aquel que se opone personal, nacional o espiritualmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2191', 'spa', 'Víbora; serpiente venenosa, usada literal y figuradamente como metáfora incisiva de peligro moral.', 'Término para designar una serpiente venenosa que lleva un gran peso metafórico en el Nuevo Testamento. Tanto Juan el Bautista como Jesús emplean la expresión ''generación de víboras'' como una reprensión mordaz, implicando que sus oyentes no solo son peligrosos sino que han heredado su naturaleza ponzoñosa. El español ''víbora'' y el francés ''vipère'' descienden de la misma raíz latina, mientras que el inglés ''viper'' capta la amenaza sibilante del griego original. La única aparición literal en Hch 28:3, donde una víbora se prende de la mano de Pablo, contrasta vívidamente con los usos figurados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2192', 'spa', 'Tener, sostener, poseer; estar en un estado o condición; poder — el verbo fundamental de posesión, relación y estado', 'El verbo griego básico para expresar posesión de objetos, relaciones con personas, estados físicos o emocionales, capacidad para hacer algo, y proximidad o conexión con algo o alguien.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2193', 'spa', 'Hasta, mientras; partícula temporal que marca el límite o la duración de una acción en el tiempo.', 'Una partícula temporal que señala el límite o el punto final de una acción en el tiempo. En su sentido dominante, ἕως significa ''hasta,'' indicando el punto en el que algo cesa o un nuevo evento comienza, como en ''hasta el día'' o Mateo 1:25 ''hasta que dio a luz un hijo.'' Con menor frecuencia se matiza como ''mientras,'' expresando duración continua en vez de terminación, como en la instrucción de Jesús de orar ''mientras yo voy allí'' (Mc 14:32). El español distingue estos sentidos con nitidez: hasta frente a mientras, confirmando la escisión semántica visible en el uso griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2194', 'spa', 'Zabulón; nombre tribal del décimo hijo de Jacob y sus descendientes', 'Zabulón (en hebreo זְבוּלוּן) es el nombre personal y tribal del décimo hijo de Jacob por medio de Lea. En el Nuevo Testamento aparece en el cumplimiento profético referente al ministerio de Jesús en Galilea: ''la tierra de Zabulón'' (Mateo 4:13, 15), y en la visión del sellado de las tribus en Apocalipsis 7:8. La tribu se asentó en la baja Galilea, de modo que el ministerio de Jesús allí cumplió la profecía de Isaías sobre la luz que resplandece en aquella región.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2195', 'spa', 'Zaqueo; nombre hebreo que significa ''puro'' o ''justo'', llevado por el jefe de los publicanos de Jericó', 'Este nombre aparece solo en el relato de Lucas sobre el rico jefe de publicanos que subió a un sicómoro para ver a Jesús a su paso por Jericó (Lucas 19). La raíz hebrea (זַכַּי) conlleva connotaciones de pureza o rectitud, un contraste irónico con el estigma social que recaía sobre los recaudadores de impuestos en la Judea del siglo I. La narrativa de Lucas gira en torno a esta tensión: aquel cuyo nombre significa ''justo'' era precisamente a quien los líderes religiosos consideraban injusto. Cuando Jesús lo llama y declara que la salvación ha llegado a su casa, la historia cumple el significado inscrito en su nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2196', 'spa', 'Zera, nombre propio que significa ''amanecer'' o ''aurora''; antepasado de Jesús', 'Zera fue uno de los hijos gemelos nacidos de Judá y Tamar (Génesis 38:30), incluido en la genealogía de Jesús según Mateo (1:3). Su nacimiento fue inusual: su mano asomó primero y la partera la marcó con un hilo escarlata, pero luego se retrajo y su gemelo Fares nació antes. Pese a ser hijo de Judá, la línea de Zera no continuó en la genealogía mesiánica; fue Fares quien llegó a ser antepasado de David y de Jesús, mientras que la mención de Zera refleja el interés de Mateo por la exactitud genealógica completa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2197', 'spa', 'Zacarías — padre sacerdotal de Juan el Bautista; también el profeta asesinado, hijo de Berequías. El nombre propio Ζαχαρίας (Zacarías) se refiere prin', 'Zacarías — padre sacerdotal de Juan el Bautista; también el profeta asesinado, hijo de Berequías. El nombre propio Ζαχαρίας (Zacarías) se refiere principalmente al anciano sacerdote de la división de Abías que llegó a ser padre de Juan el Bautista. La narrativa de la infancia de Lucas cuenta su historia: el anuncio angélico mientras quema incienso, su incredulidad y la mudez resultante, y el Benedictus cuando se le suelta la lengua en la circuncisión de Juan (Lucas 1:5-67; 3:2). Un segundo Zacarías aparece en la acusación de Jesús contra los escribas — ''la sangre de Zacarías hijo de Berequías, asesinado entre el santuario y el altar'' (Mateo 23:35; Lucas 11:51). El español Zacarías y el árabe زَكَرِيَّا conservan el nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2198', 'spa', 'Vivir, estar vivo; de la vida física, la vida de resurrección y la conducta de la existencia terrenal.', 'Ζάω es el verbo griego para la condición más fundamental de todas: estar vivo. En el Nuevo Testamento porta todo el peso de ese concepto, desde el simple hecho biológico de respirar (''el Dios viviente,'' Mt 16:16) hasta la asombrosa afirmación de que los muertos vuelven a vivir (Ap 2:8) y el imperativo ético de cómo se emplean los años de vida (Hch 26:5). El participio presente ὁ ζῶν (''el viviente'') se convierte en título divino a lo largo de las Escrituras, y la evidencia multilingüe es notablemente estable: español viviente/vivo, alemán leben, coreano 살다, todos preservan el mismo núcleo sin necesidad de vocabulario especializado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2199', 'spa', 'Zebedeo es la forma griega del hebreo Zavdiyah (''Yahvé ha concedido''), que identifica al pescador galileo cuyos hijos Jacobo y Juan dejaron sus redes ', 'Zebedeo es la forma griega del hebreo Zavdiyah (''Yahvé ha concedido''), que identifica al pescador galileo cuyos hijos Jacobo y Juan dejaron sus redes para seguir a Jesús. Las 12 apariciones en el NT funcionan como identificador patronímico — ''Jacobo hijo de Zebedeo'', ''los hijos de Zebedeo'' — situando a estos prominentes apóstoles dentro de su familia y oficio. Zebedeo mismo aparece directamente solo en la narrativa del llamamiento (Mt 4:21-22; Mr 1:19-20), donde queda en la barca remendando redes, una imagen conmovedora del costo que el discipulado tiene para una familia. Su esposa aparece en Mt 20:20 y 27:56.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2200', 'spa', 'Caliente, ardiente; que tiene alta temperatura, usado en contraste con frío y tibio para expresar fervor espiritual', 'Este adjetivo significa caliente o ardiente, y describe una temperatura elevada. Aparece exclusivamente en la carta a Laodicea del libro de Apocalipsis, en la célebre reprensión por no ser ni caliente ni frío, sino tibio. El contraste entre caliente (ζεστός), frío (ψυχρός) y tibio (χλιαρός) habla del fervor espiritual frente al compromiso mediocre. Tanto el agua caliente como la fría tienen utilidad; el agua tibia provoca repugnancia y es vomitada. Esta imagen poderosa exige una entrega total, sin medias tintas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2202', 'spa', 'Lazo o correa de yugo por donde pasa la cabeza del animal; en náutica: amarras o bandas del timón', 'Este raro término griego aparece una sola vez en el Nuevo Testamento, refiriéndose a las cuerdas o bandas que aseguraban el mecanismo de dirección de un barco. En su uso clásico, designaba el lazo sujeto al yugo por el cual se introducía la cabeza del animal de tiro. Lucas lo emplea en Hechos 27:40 durante el relato del naufragio de Pablo, cuando la tripulación suelta las amarras del timón para preparar la varada de la nave. Las glosas multilingües reflejan tanto el contexto náutico (amarras, bandas) como la incertidumbre sobre el referente técnico preciso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2205', 'spa', 'Celos o rivalidad envidiosa; celo, devoción apasionada; furia, indignación ardiente. El sustantivo griego ζῆλος encierra una tensión notable en su núc', 'Celos o rivalidad envidiosa; celo, devoción apasionada; furia, indignación ardiente. El sustantivo griego ζῆλος encierra una tensión notable en su núcleo: la misma intensidad ardiente que alimenta la devoción justa puede agriarse en envidia destructiva. Cuando Jesús purifica el templo, sus discípulos recuerdan «El celo de tu casa me consumirá» (Juan 2:17), un fuego santo. Pero cuando los saduceos actúan contra los apóstoles, están «llenos de celos» (Hechos 5:17), la misma palabra griega nombrando ahora una rabia posesiva. El español «celo» refleja esta ambiguedad perfectamente. Pablo navega ambos filos: elogia el ζῆλος de los corintios como seriedad piadosa (2 Corintios 7:11) y advierte contra el ζῆλος como espíritu partidista que los desgarraba (1 Corintios 3:3). En Hebreos 10:27, la palabra alcanza su extremo aterrador: el «ardor de fuego» reservado para el juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2206', 'spa', 'Ζηλόω es una palabra de fuego — puede calentar o puede abrasar. En el lado positivo, Pablo exhorta a los creyentes a ''procurar con empeño los dones ma', 'Ζηλόω es una palabra de fuego — puede calentar o puede abrasar. En el lado positivo, Pablo exhorta a los creyentes a ''procurar con empeño los dones mayores'' (1 Co 12:31) y a ''ser celosos por los dones espirituales'' (1 Co 14:1, 39). En el lado negativo, los patriarcas ''tuvieron envidia de José'' (Hch 7:9), y Santiago advierte que la codicia conduce al conflicto (Stg 4:2). La misma intensidad alimenta tanto la devoción como la destrucción. El español capta esta dualidad con ''anhelad'' (desear ardientemente) frente a ''teniendo celos'' (sentir envidia).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2207', 'spa', 'Zelote o devoto; persona apasionadamente comprometida con una causa, ley o tradicion; tambien epiteto ''el Zelote'' del apostol Simon.', 'Derivado de zelos (''celo, celos''), este sustantivo identifica a una persona consumida por una devocion apasionada. En su uso comun, describe un compromiso ferviente con la ley judia y las tradiciones ancestrales: Pablo se declara ''celoso de las tradiciones de mis padres'' (Ga 1:14), y los ancianos de Jerusalen senalan cuantos miles son ''celosos de la ley'' (Hch 21:20). Pablo tambien lo aplica a los dones espirituales (1 Co 14:12) y a la comunidad redimida como ''celosos de buenas obras'' (Tit 2:14). Como epiteto propio, ''el Zelote'' distingue al apostol Simon de Simon Pedro (Lc 6:15; Hch 1:13), indicando posiblemente un nacionalismo politico o simplemente una intensa devocion religiosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2208', 'spa', 'zelote, celoso; seguidor entusiasta, imitador, o miembro del partido de los Zelotes', 'Originalmente designa a un emulador o seguidor ardiente, alguien que admira e imita con pasión a otro. Los autores clásicos lo emplean para referirse a discípulos devotos de filósofos como Tucídides o Antístenes. La Septuaginta lo utiliza para traducir el hebreo que describe a Dios como «celoso» de su propia honra. En el Nuevo Testamento identifica específicamente a Simón el Zelote, uno de los Doce. El término probablemente alude al partido revolucionario judío que resistió el dominio romano, aunque también puede significar simplemente «entusiasta» o «celoso por la Ley». La palabra abarca tanto la devoción positiva como un fanatismo potencialmente peligroso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2209', 'spa', 'pérdida, daño, menoscabo; la experiencia de perder algo valioso', 'Sustantivo que denota pérdida o daño, a menudo contrapuesto a la ganancia (κέρδος). En Hechos 27 Pablo advierte a los tripulantes sobre la inminente pérdida de carga y vidas (27:10), y después les recuerda que él había predicho el daño que ahora padecen (27:21). El uso más llamativo de Pablo aparece en Filipenses 3:7-8, donde considera toda ventaja anterior como ''pérdida'' por amor a Cristo, en una metáfora deliberadamente comercial. El español ''pérdida'' refleja con exactitud este sentido coherente y unitario de privación y menoscabo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2210', 'spa', 'Sufrir pérdida, ser perjudicado o perder algo valioso como consecuencia o penalidad.', 'Siempre en voz pasiva en el NT, este verbo describe el hecho de sufrir pérdida o ser privado de algo precioso: no se trata de infligir daño a otros, sino de padecerlo uno mismo. Jesús plantea la célebre pregunta en los tres Sinópticos: «¿De qué le sirve al hombre ganar el mundo entero si pierde su propia alma?» (Mt 16:26, Mr 8:36, Lc 9:25). Pablo lo emplea respecto al constructor cuya obra deficiente es consumida por el fuego, aunque él mismo se salva «como a través del fuego» (1 Co 3:15), y de los corintios que fueron entristecidos «para que en nada fuerais perjudicados por nosotros» (2 Co 7:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2211', 'spa', 'Zenas, nombre propio (contracción de Zenodoro, ''don de Zeus''), abogado mencionado en la carta a Tito.', 'Esta forma contraída de Zenodoro (''don de Zeus'') identifica a un abogado cristiano a quien Pablo pide a Tito que asista con provisiones para su viaje. El nombre aparece únicamente en Tito 3:13, dejándonos apenas un breve destello de un profesional del derecho dentro del círculo de colaboradores de Pablo. La transliteración consistente en múltiples idiomas, con ligeras variaciones fonéticas, confirma su tratamiento universal como nombre propio. La petición de Pablo sugiere que Zenas viajaba junto con Apolos en alguna misión ministerial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2212', 'spa', 'Buscar, procurar, desear obtener; en pasiva: ser requerido o demandado.', 'Este verbo griego común, ζητέω, se mueve con fluidez entre la búsqueda física y el esfuerzo intencionado. Los magos ''buscan'' al niño (Mt 2:20) en sentido literal, mientras que Jesús ordena a sus seguidores ''buscar primeramente el reino'' (Mt 6:33) en el sentido volitivo de perseguir y priorizar. La voz pasiva introduce una tercera dimensión — la rendición de cuentas — como en Lucas 12:48: ''al que se le confió mucho, mucho se le demandará.'' El español buscar cubre tanto el sentido físico como el volitivo, pero el sentido pasivo de ''ser requerido'' exige con frecuencia una elección léxica diferente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2213', 'spa', 'Cuestión, asunto en disputa; materia de controversia jurídica o teológica que requiere resolución formal', 'Designa una cuestión disputada o un asunto sometido a investigación, con un tono más formal y solemne que el de una simple pregunta. En el Nuevo Testamento, cada aparición involucra controversias oficiales o teológicas: debates ante concilios, gobernadores o reyes. El término indica que hay más en juego que mera curiosidad; se trata de reclamaciones contenciosas que exigen una resolución autoritativa. En Hechos aparece reiteradamente en contextos de proceso judicial o deliberación conciliar, marcando la gravedad del asunto tratado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2214', 'spa', 'Indagacion, investigacion o controversia; disputa o cuestion debatida, especialmente sobre asuntos de ley o doctrina.', 'Derivado del verbo zeteo (''buscar''), este sustantivo abarca desde la indagacion filosofica hasta la controversia religiosa acalorada. En el Nuevo Testamento se inclina abrumadoramente hacia lo segundo: Jn 3:25 relata una ''disputa'' entre los discipulos de Juan y un judio sobre la purificacion; Hch 15:2,7 describen el intenso ''debate'' en el Concilio de Jerusalen sobre la circuncision; y las Epistolas Pastorales advierten contra las ''controversias'' que engendran contiendas (1 Ti 1:4; 6:4; Tit 3:9). Solo Hch 25:20 conserva el sentido mas antiguo y neutral de ''investigacion'' judicial, donde Festo confiesa su incertidumbre sobre como conducir la indagacion de los cargos contra Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2215', 'spa', 'Cizana o mala hierba (Lolium temulentum), planta toxica que imita al trigo; usada en la parabola de Jesus sobre el trigo y la cizana.', 'Termino botanico para la cizana (Lolium temulentum), una hierba venenosa que imita de cerca al trigo en sus primeras etapas de crecimiento, siendo indistinguible hasta que se forman las espigas. Las ocho apariciones en el Nuevo Testamento se encuentran dentro de la parabola de Jesus sobre el trigo y la cizana (Mt 13:24-30, 36-43), convirtiendola en uno de los sustantivos de distribucion mas restringida del Testamento griego. El poder de la parabola depende de la realidad biologica: las raices de la cizana se entrelazan con las del trigo, haciendo que arrancarla prematuramente destruya la cosecha. En espanol, ''cizana'' ha pasado al lenguaje cotidiano con el significado de ''discordia'', conservando la especificidad agricola original y anadiendo una dimension figurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2216', 'spa', 'Zorobabel; nombre propio del líder postexílico que reconstruyó el templo de Jerusalén', 'Zorobabel (del babilonio Zeru-Babili, «semilla de Babilonia») es el nombre del gobernador de Judá que encabezó el primer retorno del exilio y reconstruyó el templo bajo el decreto de Ciro. Era descendiente de David, manteniendo así la línea real. En las genealogías del Nuevo Testamento aparece como antepasado de Jesús, vinculando a Cristo tanto con la dinastía davídica como con la comunidad de la restauración. Su inclusión subraya la fidelidad de Dios a través del exilio y el regreso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2217', 'spa', 'Tinieblas densas, oscuridad profunda; la negrura lóbrega del inframundo o del juicio divino', 'Designa una oscuridad espesa y opresiva asociada con el pavor y el castigo divino. A diferencia del simple anochecer, esta palabra evoca la lobreguez primordial del inframundo; Homero la empleaba para el reino del Hades. En el Nuevo Testamento aparece exclusivamente en contextos de juicio escatológico: cadenas de tinieblas, la más densa oscuridad reservada para los impíos. Su gravedad poética la hace mucho más pesada que los términos comunes para la oscuridad, transmitiendo un horror envolvente y absoluto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2218', 'spa', 'Yugo: travesaño de madera para animales de tiro; extendido a cargas de obligación, servidumbre o una balanza.', 'En el mundo antiguo, el ζυγόν era el conocido armazón de madera que unía a los bueyes al arado, y se convirtió en una de las metáforas más poderosas de la Escritura. Jesús invita a los cansados a tomar su yugo, prometiendo que es fácil y ligero (Mt 11:29-30), en deliberado contraste con el pesado yugo legalista que los apóstoles se niegan a imponer (Hch 15:10). Pablo advierte contra volver a un «yugo de esclavitud» (Gá 5:1), y se indica a los esclavos que honren a sus amos bajo el yugo (1 Ti 6:1). En Apocalipsis 6:5 la palabra cambia a un par de balanzas sostenidas por el tercer jinete, señalando hambruna y juicio económico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2219', 'spa', 'Levadura, fermento; agente de fermentación usado literalmente para la elaboración de pan y figuradamente para la influencia moral o doctrinal que se e', 'Levadura, fermento; agente de fermentación usado literalmente para la elaboración de pan y figuradamente para la influencia moral o doctrinal que se extiende de manera penetrante. En el mundo antiguo se reservaba un trozo de masa vieja para leudar la nueva hornada, lo cual hacía natural y poderosa la imagen de una influencia oculta que se propaga. Jesús advierte a sus discípulos que se guarden de la levadura de los fariseos (Mt 16:6; Mr 8:15; Lc 12:1), empleando la palabra como metáfora de la expansión silenciosa de la enseñanza corrupta. Sin embargo, en Mt 13:33 la misma imagen aparece en sentido positivo: el reino de los cielos es como la levadura que una mujer escondió en harina hasta que todo quedó leudado. Pablo retoma la metáfora en 1 Co 5:6-8 y Gá 5:9, advirtiendo que un poco de levadura leuda toda la masa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2220', 'spa', 'Leudar, hacer fermentar; impregnar por completo como la levadura en la masa', 'Derivado de ζύμη (levadura), este verbo describe el proceso mediante el cual una pequeña porción de levadura impregna y transforma toda la masa. Jesús lo emplea positivamente en las parábolas del reino (Mt 13:33; Lc 13:21), donde una mujer esconde levadura en tres medidas de harina hasta que toda la masa queda leudada. Pablo invierte la imagen: un poco de levadura leuda toda la masa, advirtiendo contra la tolerancia del pecado en la comunidad (1 Co 5:6; Gá 5:9). El verbo abarca tanto el proceso literal de panificación como su poderosa fuerza figurada de transformación total.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2222', 'spa', 'Vida — existencia biológica y, de modo distintivo en el NT, la cualidad eterna de vida que procede de Dios por medio de Cristo', 'ζωή en el griego clásico podía significar sustento o simplemente el estado de estar vivo. El Nuevo Testamento transforma radicalmente el término: la gran mayoría de sus 135 apariciones no designan la mera existencia biológica, sino la cualidad divina e imperecedera de vida que pertenece a Dios y se otorga mediante la fe en Cristo. El Evangelio de Juan está especialmente saturado de este uso — «Yo soy el camino, la verdad y la vida» (Jn 14:6); «Yo he venido para que tengan vida, y la tengan en abundancia» (Jn 10:10). Pablo contrasta esta vida con la muerte como paga del pecado (Ro 6:23). El adjetivo αἰώνιος (''eterna'') modifica frecuentemente a ζωή, pero incluso sin él, la palabra a menudo implica la plenitud de la vitalidad propia de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2223', 'spa', 'Cinturon, cinto o faja usada alrededor de la cintura; parte del atuendo de profetas y viajeros.', 'Derivado de ζώννυμι (''cenir''), ζώνη designa un cinturon o faja atada a la cintura, con funciones tanto practicas como simbolicas. El cinturon de cuero de Juan el Bautista (Mt 3:4; Mc 1:6) evoca deliberadamente el cinto de Elias (2 Re 1:8), senalando identidad profetica. Jesus instruye a los Doce a no llevar dinero en sus cinturones (Mt 10:9; Mc 6:8), como marca de dependencia radical de Dios. El profeta Agabo se ata las manos y los pies con el cinturon de Pablo como profecia dramatizada (Hch 21:11), mientras que las fajas doradas de las figuras celestiales en Apocalipsis (Ap 1:13; 15:6) elevan la prenda a esplendor celestial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2224', 'spa', 'Ceñir, ajustar el cinturón; sujetar las vestiduras alrededor de la cintura, especialmente para trabajar o viajar', 'Este verbo significa ceñirse, ajustar un cinturón o recoger las vestiduras holgadas alrededor de la cintura. En la cultura antigua, esto preparaba a una persona para la actividad vigorosa, el trabajo o el viaje. El término aparece en la profecía de Jesús a Pedro sobre su futuro (Juan 21:18), contrastando el ceñirse por sí mismo en la juventud con ser ceñido por otro para el martirio en la vejez. También aparece en la instrucción del ángel al Pedro encarcelado (Hechos 12:8), ordenándole vestirse y ceñirse para escapar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2225', 'spa', 'Preservar con vida, dar vida, mantener vivo; producir o engendrar seres vivientes', 'Este verbo griego capta el acto divino de preservar y sostener la vida. Aparece en Lucas 17:33, donde Jesús promete vida a quienes pierden su existencia terrenal; en Hechos 7:19, describiendo la cruel orden del faraón contra los niños hebreos; y en 1 Timoteo 6:13, atribuyendo a Dios el poder de dar vida a todas las cosas. La evidencia multilingüe abarca desde «dar vida» hasta «mantener con vida», reflejando tanto el sentido causativo (traer a la vida) como el preservativo (mantener vivo). El Nuevo Testamento se centra en el poder soberano de Dios sobre la vida y la muerte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2226', 'spa', 'Ser viviente o animal; en Apocalipsis, los cuatro seres vivientes celestiales alrededor del trono de Dios', 'Ser viviente o animal; en Apocalipsis, los cuatro seres vivientes celestiales alrededor del trono de Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2227', 'spa', 'Dar vida, vivificar; pasivo: ser vivificado, ser resucitado a vida — del poder divino que da vida. El verbo griego ζωοποιέω fusiona ζωή (''vida'') con π', 'Dar vida, vivificar; pasivo: ser vivificado, ser resucitado a vida — del poder divino que da vida. El verbo griego ζωοποιέω fusiona ζωή (''vida'') con ποιέω (''hacer''), creando una palabra casi exclusivamente teológica en el Nuevo Testamento: dar vida, vivificar. Jesús declara que ''como el Padre levanta a los muertos y les da vida, así también el Hijo da vida a quien quiere'' (Juan 5:21), y ''el Espíritu es el que da vida; la carne para nada aprovecha'' (Juan 6:63). En la voz pasiva, la palabra se convierte en piedra angular de la teología de la resurrección: ''en Cristo todos serán vivificados'' (1 Corintios 15:22), y Cristo mismo fue ''muerto en la carne pero vivificado en el espíritu'' (1 Pedro 3:18). El español vivificar, el francés vivifier y el alemán lebendig machen recurren a vocabulario compuesto de dar-vida. El verbo insiste en que la vida no es autogenerada sino otorgada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2228', 'spa', 'O (presentando alternativas), o que (tras comparativos); la conjunción disyuntiva y comparativa principal del griego', 'Una conjunción breve pero fundamental que cumple una doble función en el Nuevo Testamento. En la gran mayoría de sus 352 apariciones significa «o», presentando alternativas una junto a otra — como cuando Jesús insiste en que nadie puede servir a dos señores: «o aborrecerá al uno y amará al otro» (Mt 6:24). Sin embargo, tras adjetivos comparativos se transforma en «que», como en «más tolerable será para Sodoma que para aquella ciudad» (Mt 10:15). El español distingue claramente ambos usos con partículas distintas: «o» para la disyunción y «que» para la comparación, confirmando la diferencia semántica real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2229', 'spa', 'verdaderamente, ciertamente, en verdad (partícula de afirmación o aseveración)', 'Adverbio que confirma aserciones con la fuerza de «verdaderamente», «ciertamente» o «en efecto». Homero y los autores clásicos lo emplean para reforzar declaraciones, frecuentemente en juramentos y afirmaciones solemnes. Puede aparecer solo o combinarse con otras partículas (ἦ ἄρα, ἦ μήν) para mayor énfasis. En juramentos y aseveraciones subraya la certeza de lo que sigue: «en verdad, juro ayudarte». A veces posee un matiz concesivo: «es cierto que...» o «aunque...». La partícula nunca aparece en la forma ἦε, siempre ἦ. Su sola presencia intensifica la convicción del enunciado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2231', 'spa', 'Gobierno, reinado o autoridad política; el período o administración de un gobernante; ejercicio del poder.', 'Este término designa el ejercicio del poder político y la autoridad, ya sea por un comandante militar, un líder político o un soberano. En el griego clásico abarcaba desde el mando en el campo de batalla hasta la dirección de escuelas filosóficas. Lucas lo emplea una sola vez para fechar el inicio del ministerio de Juan el Bautista, anclando la narrativa en el año decimoquinto del reinado de Tiberio César. La palabra enfatiza no solo el cargo, sino el ejercicio activo del control gubernamental durante un período determinado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2232', 'spa', 'Un líder o gobernante; en el NT especialmente un gobernador provincial romano como Pilato o Félix. En el griego clásico, ἡγεμών abarca cualquier tipo ', 'Un líder o gobernante; en el NT especialmente un gobernador provincial romano como Pilato o Félix. En el griego clásico, ἡγεμών abarca cualquier tipo de líder: un guía, un comandante militar, un jefe. Para la época romana se había convertido en el término estándar para designar a un gobernador provincial, y así es abrumadoramente como lo usa el Nuevo Testamento. A Poncio Pilato se le llama ἡγεμών a lo largo de los relatos de la Pasión (Mt 27:2, 11, 14), mientras que Jesús advierte a sus discípulos que serán llevados ante ἡγεμόνες y reyes (Mt 10:18; Mc 13:9). Mateo 2:6 aplica de manera singular la palabra al gobernante prometido de Belén, haciendo eco de Miqueas 5:2 con matices mesiánicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2233', 'spa', 'Considerar, estimar, tener por; también dirigir, guiar o gobernar — un verbo que abarca cognición y autoridad', 'Considerar, estimar, tener por; también dirigir, guiar o gobernar — un verbo que abarca cognición y autoridad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2234', 'spa', 'Con gusto, gustosamente, de buena gana; forma adverbial que expresa aceptación gozosa o deleite', 'Este adverbio, derivado del adjetivo que significa «dulce» o «agradable», describe el hacer algo con genuino placer y entusiasmo. Aparece cuando Herodes escuchaba a Juan el Bautista con fascinación a pesar de sentirse perturbado por su mensaje (Marcos 6:20), cuando las multitudes oían a Jesús con gusto (Marcos 12:37) y cuando Pablo señala irónicamente la disposición de los corintios a tolerar a los necios (2 Corintios 11:19). La palabra no expresa mera conformidad sino recepción entusiasta, aunque el uso paulino conlleva un matiz de ironía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2235', 'spa', 'ἤδη — ya, a estas alturas; adverbio temporal que indica tiempo cumplido o alcanzado', 'El adverbio ἤδη (''ya'') señala que un evento o estado ha llegado a un punto antes de lo esperado o para el momento en que se habla. Aparece en coyunturas narrativas decisivas: las multitudes ''ya'' llevan tres días con Jesús y no tienen qué comer (Mt 15:32), la hora ''ya'' es avanzada (Mt 14:15), y quien mira con codicia ''ya'' ha cometido adulterio en su corazón (Mt 5:28). Este último uso es teológicamente llamativo: ἤδη elimina la distancia entre la intención y el acto. Con 61 apariciones en el Nuevo Testamento, el término se traduce con precisión uniforme en las lenguas principales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2237', 'spa', 'Placer, deleite sensual; deseo de gratificación que compite con la devoción a Dios', 'Designa el placer o el goce, especialmente de índole sensual o autocomplaciente. En el griego clásico el término abarcaba un amplio espectro desde el deleite corporal hasta la satisfacción intelectual, pero en el Nuevo Testamento lleva consistentemente una carga negativa: placeres que ahogan la fe, esclavizan la voluntad o alimentan el conflicto. Cada contexto neotestamentario presenta este placer como espiritualmente corrosivo. La penetrante pregunta de Santiago sobre el origen de los conflictos (Stg 4:1) lo localiza precisamente en estos apetitos desordenados que batallan en los miembros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2239', 'spa', 'Hábitos, costumbres, modales; patrones de comportamiento arraigados; formas de vida o carácter moral.', 'Esta palabra abarca tanto las costumbres externas como las disposiciones internas de carácter. En el griego clásico podía referirse a los hábitats de los animales, las costumbres de los pueblos o los rasgos de carácter arraigados en las personas. Pablo cita a un poeta griego en 1 Corintios 15:33 para advertir que las malas compañías corrompen las buenas costumbres. La forma plural empleada aquí enfatiza patrones de conducta más que un rasgo aislado. La evidencia multilingüe muestra cómo los traductores oscilan entre ''costumbres'', ''hábitos'' y ''carácter'' al verter este término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2240', 'spa', 'venir, llegar, estar presente — verbo de llegada con un matiz distintivo de presente con fuerza de perfecto', 'venir, llegar, estar presente — verbo de llegada con un matiz distintivo de presente con fuerza de perfecto');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2242', 'spa', 'Helí, nombre propio del padre de José en la genealogía de Jesús según Lucas; posible variante del hebreo Elí.', 'Este nombre aparece exclusivamente en la genealogía de Jesús que presenta Lucas, identificando al padre de José. Probablemente representa una forma griega del hebreo Elí, que significa ''mi Dios'' o ''ascensión''. La genealogía de Lucas difiere de la de Mateo en este punto, lo que ha generado un extenso debate sobre si Lucas traza la línea de María o emplea un cómputo diferente. La transliteración consistente en múltiples idiomas refleja su condición de nombre propio, con ligeras variaciones vocálicas según las convenciones fonéticas de cada lengua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2243', 'spa', 'Elías (Ēlías), el célebre profeta del AT referido en el NT como precursor y figura escatológica', 'Elías (Ēlías), el célebre profeta del AT referido en el NT como precursor y figura escatológica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2244', 'spa', 'Estatura o altura corporal; edad, madurez o etapa de la vida', 'Una palabra que mantiene en tensión creativa dos ideas relacionadas pero distintas: la estatura física y el transcurso de la edad. Cuando Lucas dice que Jesús ''crecía en estatura'' (Lc 2:52), se refiere a su altura corporal; cuando Zaqueo es ''pequeño de estatura'' (Lc 19:3), es su baja estatura la que lo impulsa a subir al sicómoro. En Juan 9:21, 23 el mismo vocablo significa ''de edad'': el ciego de nacimiento tiene edad suficiente para hablar por sí mismo. El enigma de Mt 6:27 y Lc 12:25 gira sobre esta ambigüedad: ¿habla Jesús de agregar altura o de alargar la vida? El español distingue ''estatura'' de ''edad'', pero el griego reúne ambos sentidos en un solo término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2245', 'spa', 'cuán grande, cuán pequeño; expresa grado o magnitud en preguntas y exclamaciones, ya sea de grandeza o de pequeñez', 'Este adjetivo griego interroga sobre el tamaño, la edad o la magnitud, y puede expresar asombro tanto ante lo enormemente grande como ante lo sorprendentemente pequeño. Santiago lo emplea dos veces en un mismo versículo para ilustrar el poder de la lengua: «¡cuán pequeño fuego enciende cuán gran bosque!» (Santiago 3:5). Pablo lo usa en Colosenses 2:1 para describir su gran lucha por las iglesias. La palabra opera en preguntas indirectas y exclamaciones de admiración, y su fuerza es comparativa y frecuentemente emotiva, resaltando la desproporción o una escala inesperada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2246', 'spa', 'sol — el astro como fuente de luz, calor y metáfora de gloria radiante o juicio divino', 'sol — el astro como fuente de luz, calor y metáfora de gloria radiante o juicio divino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2248', 'spa', 'nos, a nosotros (pronombre personal de primera persona plural en acusativo); caso objetivo de «nosotros»', 'Forma acusativa del pronombre personal de primera persona plural, que funciona como complemento directo de verbos o término de preposiciones: «nos envió», «por nosotros», «con nosotros». Al igual que el singular ἐγώ, los casos oblicuos del plural provienen de una raíz distinta a la del nominativo. Los autores del Nuevo Testamento emplean esta forma constantemente para describir las acciones de Dios hacia la humanidad («de tal manera nos amó Dios») y la comunidad apostólica («se nos apareció»). Las cartas de Pablo abundan en lenguaje corporativo: lo que nos sucedió, lo que se nos dio, cómo Cristo habita entre nosotros. El pronombre marca experiencia compartida e identidad colectiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2249', 'spa', 'nosotros (pronombre personal de primera persona plural en nominativo); los que hablan o escriben como grupo', 'Pronombre personal de primera persona plural en caso nominativo, que identifica al hablante junto con otros como sujeto de una acción o estado. Pablo lo utiliza extensamente para describir el testimonio apostólico («proclamamos»), la experiencia cristiana compartida («tenemos paz con Dios») y la identidad comunitaria. El griego antiguo presenta variantes dialectales —épico e jónico εἰμέν, dórico εἰμές— pero la función básica permanece constante. El pronombre puede ser inclusivo (abarcando a la audiencia) o exclusivo (distinguiendo al grupo del hablante). En Hechos, los pasajes con «nosotros» señalan narración de testigos oculares. Simple pero indispensable para la voz corporativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2250', 'spa', 'Día — un día del calendario o período de tiempo; también las horas de luz diurna en contraste con la noche', 'ἡμέρα es la palabra estándar del Nuevo Testamento para «día», con cerca de 400 apariciones que abarcan una notable variedad de expresiones temporales: desde fechas específicas del calendario y períodos contados de días, hasta frases de gran carga teológica como «el día del juicio» (Mt 10:15) y «aquel día» que apunta al cumplimiento escatológico. En un puñado de pasajes, ἡμέρα se estrecha para designar específicamente la porción diurna del ciclo de veinticuatro horas, contrastada explícitamente con la noche — como cuando Jesús pregunta: «¿No tiene el día doce horas?» (Jn 11:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2251', 'spa', 'Nuestro, nuestra; pronombre posesivo de primera persona plural que indica pertenencia compartida', 'El pronombre posesivo enfático de primera persona plural. ἡμέτερος añade peso más allá del simple genitivo ἡμῶν (''de nosotros''). En Hechos 2:11 la multitud se maravilla al escuchar ''nuestras lenguas'' --los idiomas de diversas naciones-- hablados por galileos, de modo que el pronombre funciona como marcador de identidad étnica y cultural. Pablo lo emplea para afirmar una herencia compartida: ''nuestra religión'' (Hch 26:5), ''escrito para nuestra instrucción'' (Ro 15:4). La palabra aparece en contextos donde se subraya la posesión comunitaria o el interés compartido, ya sea de fe, lengua o herencia escritural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2252', 'spa', 'yo era, tú eras (imperfecto de primera/segunda persona singular de εἰμί); existencia o estado pasado', 'Formas de primera y segunda persona del singular del imperfecto del verbo «ser/estar», que describen estados continuos o existencia habitual en el pasado: «yo era», «tú eras». En la narración establece las condiciones de fondo o introduce las circunstancias de los personajes antes de que se desarrollen los acontecimientos. El testimonio personal lo emplea para contrastar pasado y presente: «yo era ciego, pero ahora veo». La cualidad aspectual del imperfecto enfatiza duración o repetición en el tiempo pasado, no un evento puntual sino un estado prolongado. Las variaciones dialectales abundan, pero el significado esencial permanece estable en toda la literatura griega.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2253', 'spa', 'Medio muerto, casi muerto; en un estado entre la vida y la muerte, gravemente herido o golpeado.', 'Este vívido adjetivo compuesto aparece únicamente en la parábola del Buen Samaritano, describiendo al viajero que los ladrones dejaron apenas con vida. El griego combina ''medio'' (ἡμι-) con ''muerto'' (θανής) para crear una imagen cruda de alguien que oscila entre la vida y la muerte. El término subraya la condición desesperada y la indefensión de la víctima, lo que hace aún más conmovedor el acto de compasión del samaritano. Los traductores en diversos idiomas preservan la imagen dramática de ''medio muerto'', mostrando el poder universal de esta descripción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2254', 'spa', 'nos, a nosotros (pronombre de primera persona plural en dativo); objeto indirecto o caso relacional', 'Forma en caso dativo del pronombre de primera persona plural, que funciona como objeto indirecto («nos dio», «nos habló») o expresa relación e interés («nos aconteció», «es para nosotros»). Los autores del Nuevo Testamento emplean esta forma con frecuencia al describir la acción divina hacia la comunidad creyente: la gracia que nos fue dada, el Espíritu derramado sobre nosotros, las promesas hechas a nosotros. Las cartas paulinas abundan en construcciones de dativo que marcan la disposición de Dios hacia su pueblo. Este caso también aparece tras ciertas preposiciones. Al igual que otras formas pronominales oblicuas, deriva de una raíz distinta a la del nominativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2255', 'spa', 'Mitad; una de dos partes iguales, usado para cantidades, períodos de tiempo y porciones', 'El adjetivo griego estándar para ''mitad'', que aparece en el Nuevo Testamento tanto en contextos narrativos como apocalípticos. El juramento temerario de Herodes ofrece ''la mitad de mi reino'' (Mr 6:23), Zaqueo promete la mitad de sus bienes a los pobres (Lc 19:8), y Apocalipsis mide el tiempo profético en mitades: tres días y medio, un tiempo y tiempos y medio tiempo. El español distingue ''mitad'' (sustantivo) de ''medio'' (adjetivo), reflejando bien la flexibilidad del término entre sus usos sustantivados y atributivos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2256', 'spa', 'Media hora, un periodo de treinta minutos; un breve intervalo temporal.', 'Esta medida temporal precisa aparece únicamente en la visión apocalíptica de Apocalipsis, describiendo un silencio profundo en el cielo. El compuesto une «medio» (ἡμι-) con «hora» (ὥρα) para crear una duración exacta. En la secuencia dramática de Apocalipsis 8:1, este silencio de media hora sigue a la apertura del séptimo sello, generando un momento de suspenso cósmico antes de los juicios de las trompetas. La especificidad de este marcador temporal refuerza la precisión profética de la visión de Juan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2257', 'spa', 'de nosotros, nuestro (pronombre de primera persona plural en genitivo); posesivo o de procedencia', 'Forma en caso genitivo del pronombre de primera persona plural, que expresa posesión («nuestra fe»), origen («uno de entre nosotros») o relación («la esperanza de todos nosotros»). El griego antiguo dispone también de una forma enclítica más breve para posiciones menos enfáticas. El rango semántico del genitivo incluye el sentido partitivo («algunos de nosotros»), el genitivo subjetivo («nuestro amor por Dios») y el genitivo objetivo («el amor de Dios por nosotros»). Los autores bíblicos entrelazan esta forma a lo largo de la teología comunitaria: nuestra salvación, nuestro Señor, el cuerpo de los que creemos. La relación genética del pronombre une al hablante y a la audiencia en una experiencia o posesión compartida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2258', 'spa', 'yo era, él/ella era (imperfecto de indicativo de εἰμί); existencia pasada durativa', 'Imperfecto de indicativo del verbo «ser/estar» en primera o tercera persona, que describe estados pasados continuos o condiciones habituales. En los distintos dialectos presenta variaciones características: formas épicas, dóricas y el estándar ático. En la narrativa pinta el trasfondo de la escena: «había un hombre», «Jesús estaba en el desierto», «iban por el camino». Los relatos de testimonio y conversión contrastan lo que se era con lo que ahora se es. El carácter aspectual del imperfecto se demora en el tiempo pasado, describiendo duración en vez de eventos puntuales. Simple pero esencial para la narración y la reflexión teológica sobre el cambio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2260', 'spa', 'Que (partícula comparativa enfática); más que, antes que; usada para intensificar comparaciones.', 'Esta forma intensificada de la partícula comparativa «que» añade énfasis o incluso sorpresa a las comparaciones. La adición de la partícula enclítica refuerza la comparación, sugiriendo «más que incluso» o «antes que». Juan la emplea una vez para describir a quienes valoraban la alabanza humana por encima de la aprobación divina. El término aparece en la poesía clásica y la prosa elevada para hacer las comparaciones más contundentes. Las traducciones modernas suelen traducirla simplemente como «que», aunque el griego conlleva un peso retórico adicional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2261', 'spa', 'Amable, bondadoso, apacible; indulgente y benigno en carácter; moderado y tierno.', 'Este hermoso adjetivo describe una disposición amable y bondadosa que trata a los demás con dulzura en lugar de aspereza. El uso clásico lo aplicaba a gobernantes benévolos, deidades apaciguadas, palabras suaves e incluso al clima templado o a fiebres leves. Pablo exige que el siervo del Señor posea esta cualidad, contrastándola con el espíritu pendenciero. El término no sugiere debilidad sino fortaleza bajo control: poder ejercido con bondad. Aparece en contextos que describen tanto el carácter interior como la conducta exterior, la disposición interna manifestándose en gentileza visible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2262', 'spa', 'Er, nombre propio en la genealogía de Jesús según Lucas; nombre hebreo que significa «vigilante» o «despierto».', 'Este nombre hebreo aparece en el registro genealógico de Jesús según Lucas, representando a uno de los antepasados en la línea que va de David a José. El nombre Er (hebreo עֵר) aparece varias veces en el Antiguo Testamento, siendo el más notable el hijo primogénito de Judá. En Génesis, Er fue herido de muerte por el Señor a causa de su maldad, aunque el Er de la genealogía lucana es un individuo distinto de una generación posterior. La breve mención no ofrece detalles más allá del nombre mismo, preservado en las traducciones con ligeras variaciones fonéticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2263', 'spa', 'Tranquilo, apacible, pacífico; sereno y calmado; libre de agitación o perturbación.', 'Este adjetivo describe un estado de quietud y tranquilidad, libre de perturbaciones o tumultos. Puede caracterizar tanto circunstancias externas como disposiciones internas. Pablo lo emplea en sus instrucciones sobre la oración por las autoridades, esperando que los creyentes puedan llevar una vida tranquila y pacífica. El término sugiere no solo la ausencia de ruido sino la libertad frente al caos, la persecución o la agitación social. El uso clásico lo aplicaba a vidas apacibles, tratamientos médicos suaves y superficies lisas, compartiendo todos la cualidad de una paz imperturbable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2264', 'spa', 'Herodes — miembros de la dinastía herodiana: Herodes el Grande, Herodes Antipas y Herodes Agripa I', 'Herodes — miembros de la dinastía herodiana: Herodes el Grande, Herodes Antipas y Herodes Agripa I');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2265', 'spa', 'Herodianos; partidarios o simpatizantes de la dinastía de Herodes y sus políticas', 'Los herodianos eran una facción política que apoyaba la dinastía herodiana y su acomodación al dominio romano. En los Evangelios aparecen como aliados inesperados de los fariseos en su oposición a Jesús. En Marcos 3:6 conspiran con los fariseos para destruir a Jesús tras la controversia sobre la sanación en sábado. En Marcos 12:13 y Mateo 22:16 se unen para tenderle una trampa con la pregunta sobre el pago de impuestos al César. El Nuevo Testamento los presenta siempre en alianza táctica con los fariseos, a pesar de sus orientaciones opuestas, lo cual subraya la amenaza que Jesús representaba para las distintas estructuras de poder.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2266', 'spa', 'Herodías; nieta de Herodes el Grande, esposa de Herodes Antipas, quien maquinó la ejecución de Juan el Bautista.', 'Nombre propio de la mujer que abandonó a su esposo Felipe para casarse con su hermano Herodes Antipas, lo cual provocó la denuncia pública de Juan el Bautista y, finalmente, ella orquestó su decapitación. Las seis ocurrencias en el NT se concentran en dos relatos paralelos: Mateo 14:3-6 y Marcos 6:17-22, con Lucas 3:19 añadiendo una referencia resumida. El relato de Marcos es notablemente más detallado, especificando el papel de Herodías en la conspiración y la danza de su hija. El nombre se preserva en español como «Herodías» siguiendo el patrón flexivo griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2267', 'spa', 'Herodión, nombre propio; cristiano en Roma saludado por Pablo como ''mi pariente''.', 'Este nombre aparece únicamente en los saludos de Pablo al final de Romanos, donde identifica a Herodión como ''mi pariente'' (συγγενῆ μου), lo cual sugiere herencia judía y posiblemente un vínculo familiar. El nombre deriva de Herodes, aunque esto no implica conexión alguna con la dinastía gobernante, ya que los nombres basados en Herodes eran comunes en la época. La designación ''pariente'' podría significar compatriota judío o familiar consanguíneo. Como muchos en la lista de saludos de Pablo, conocemos a Herodión solo por este cálido reconocimiento de comunión cristiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2268', 'spa', 'Isaías — el profeta hebreo, hijo de Amoz, cuyos escritos son la fuente veterotestamentaria más citada en el NT', 'Isaías — el profeta hebreo, hijo de Amoz, cuyos escritos son la fuente veterotestamentaria más citada en el NT');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2269', 'spa', 'Esaú, hijo mayor de Isaac, gemelo que vendió su primogenitura a Jacob', 'Esaú, hijo de Isaac y Rebeca, aparece en tres referencias significativas del Nuevo Testamento. Romanos 9:13 cita a Malaquías: «A Jacob amé, mas a Esaú aborrecí», en la argumentación de Pablo sobre la elección divina. Hebreos 11:20 menciona la bendición de Isaac a Jacob y Esaú como un acto de fe. Hebreos 12:16 usa a Esaú como ejemplo admonitorio de persona «profana» que «por una sola comida vendió su primogenitura». El nombre proviene del hebreo עֵשָׂו. El Nuevo Testamento presenta consistentemente a Esaú como tipo teológico: aquel que despreció su herencia, en contraste con Jacob, que valoró la bendición espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2270', 'spa', 'Callar, descansar, guardar silencio; cesar de actividad o de hablar, aquietarse', 'Verbo que significa guardar silencio, descansar del trabajo o dejar de hablar. Abarca tanto el reposo físico como el cese de la palabra o la oposición. Cuando los discípulos ''callaron'' ante la obra evidente de Dios (Hch 11:18, 21:14), el término transmite una aquiescencia reverente más que simple mudez. Pablo incluso lo prescribe como estilo de vida: ''aspirad a vivir tranquilamente'' (1 Ts 4:11). El español capta este abanico con ''callaron'' (enmudecieron) junto a ''estar quietos'' (reposar), mostrando el doble eje de silencio y quietud propio de esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2271', 'spa', 'Quietud, silencio, calma; estado de sosiego interior o compostura apacible', 'Este sustantivo abarca un campo semántico que va desde el silencio exterior hasta la tranquilidad interior. Aparece en contextos donde la calma se restaura o se prescribe. Cuando Pablo habla en arameo, la multitud de Jerusalén guarda un profundo silencio (Hch 22:2). En las Epístolas Pastorales describe la actitud ordenada y pacífica que se espera en la vida comunitaria: trabajar con sosiego (2 Ts 3:12) y aprender con quietud (1 Ti 2:11-12). El término captura tanto el silencio audible como la serenidad compuesta del espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2273', 'spa', 'O bien... o; partícula disyuntiva que introduce alternativas; sea... o.', 'Esta conjunción introduce opciones o posibilidades alternativas, estableciendo una construcción disyuntiva de tipo ''o bien... o''. Pablo la emplea en Romanos 6 para presentar la elección fundamental que enfrenta toda persona: somos esclavos o del pecado que conduce a la muerte, o de la obediencia que conduce a la justicia. La partícula puede introducir la primera alternativa o aparecer entre ambas opciones. En el uso clásico se empleaba en contextos filosóficos y retóricos para presentar alternativas claras. Este marco disyuntivo exige una decisión y no permite término medio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2274', 'spa', 'ser vencido, derrotado, superado; ser inferior o menor que otro', 'Este verbo griego en voz pasiva expresa ser vencido, derrotado o hecho inferior. Pedro lo emplea dos veces en 2 Pedro 2:19-20 para describir la esclavitud a la corrupción y al pecado: las personas son esclavas de aquello que las vence, y quienes escapan de la corrupción pero recaen son «vencidas» de nuevo. En 2 Corintios 12:13 Pablo lo usa con ironía, preguntando en qué fueron los corintios «inferiores» a otras iglesias, excepto en que él no les fue carga económica. El Nuevo Testamento se centra en la derrota moral y espiritual, el estado de ser dominado por el pecado o el vicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2277', 'spa', 'que sea, sea (forma tardía del imperativo de εἰμί); mandato o permiso en tercera persona', 'Forma tardía del griego que funciona como imperativo de tercera persona singular del verbo «ser», funcionalmente equivalente al más antiguo ἔστω. Expresa mandato, permiso o deseo: «que sea», «así sea». Esta forma aparece en textos a partir del siglo III d.C., y representa la evolución lingüística del griego koiné y posterior. Al igual que otras formas imperativas de este verbo, posee peso performativo en bendiciones, decretos y oraciones. El acto simple de ordenar el ser subraya el poder creador y autoritativo de la palabra hablada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2278', 'spa', 'Sonar, resonar, retumbar; producir un ruido fuerte; hacer eco o reverberar.', 'Este verbo describe un sonido fuerte y resonante: el tañido del metal, el chirrido de los insectos, el repique de la música. Puede ser transitivo (hacer sonar algo) o intransitivo (sonar por sí mismo). Pablo lo usa metafóricamente en 1 Corintios 13 para describir el ruido vacío del habla sin amor. En el uso clásico abarcaba desde el resonar de escudos en batalla hasta el zumbido en los oídos y los ecos de instrumentos musicales. El vocablo capta no un simple sonido, sino un sonido resonante y reverberante que llena el espacio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2279', 'spa', 'Sonido, ruido, estruendo; un eco o reporte reverberante', 'Forma tardía del clásico ἠχή, este sustantivo designa cualquier sonido reverberante, desde el rugido del viento hasta el bramido del mar o el estallido de una trompeta. En Pentecostés, un sonido como de viento impetuoso llena toda la casa (Hch 2:2). Lucas 21:25 habla del bramido del mar y las olas como señal apocalíptica. En Hebreos 12:19 describe el sonido aterrador de la trompeta en el Sinaí. La palabra también puede significar ''fama'' o ''noticia'' (Lc 4:37), donde la metáfora del sonido que se propaga capta cómo se difunden las noticias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2281', 'spa', 'Mar; gran masa de agua, ya sea un mar específico con nombre o el mar como entidad cósmica', 'θάλασσα es el término griego estándar para el mar, y abarca toda gran extensión de agua en el Nuevo Testamento: el mar de Galilea donde Jesús calma la tempestad (Mt 8:26), el mar Rojo del Éxodo recordado en Hebreos 11:29, y el Mediterráneo implícito en los relatos de navegación de Hechos. También posee significado apocalíptico: en Apocalipsis 21:1 el mar ya no existe, simbolizando el fin del caos y la separación. Su unidad semántica queda confirmada por la convergencia unánime de las traducciones: español ''mar'', francés ''mer'', alemán ''Meer'', a lo largo de sus 91 apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2283', 'spa', 'Tamar, nombre propio; mujer en la genealogía de Jesús, madre de Fares y Zara por medio de Judá.', 'Este nombre hebreo (תָּמָר, que significa ''palmera'' o ''palma datilera'') identifica a una de las mujeres notables que Mateo incluye en la genealogía de Jesús. La historia de Tamar en Génesis 38 involucra engaño y escándalo: privada de sus derechos como viuda sin hijos, se disfrazó y concibió gemelos de su suegro Judá. A pesar de las circunstancias irregulares, aseguró su lugar en la línea mesiánica. Su inclusión por parte de Mateo, junto con Rajab, Rut y Betsabé, destaca cómo los propósitos de Dios obran a través de personas y circunstancias inesperadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2284', 'spa', 'Asombrarse, quedar atónito o alarmarse; reacción abrumadora de estupor o temor ante lo inesperado', 'Un verbo vívido para ese tipo de asombro que deja paralizado. En el Evangelio de Marcos, esta palabra capta la reacción estupefacta de la multitud ante la enseñanza y los exorcismos de Jesús realizados con autoridad (Mr 1:27), la alarma de los discípulos ante sus dichos difíciles sobre la riqueza (Mr 10:24) y su creciente temor cuando él se encaminó resueltamente hacia Jerusalén (Mr 10:32). El término designa una reacción que va más allá de la sorpresa ordinaria, mezclando asombro reverente con un matiz de sobrecogimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2285', 'spa', 'asombro, estupor, admiración; sorpresa abrumadora o sobrecogimiento ante el poder divino', 'Este sustantivo describe la reacción de estupor de los testigos ante el poder divino. En Lucas 4:36 capta la respuesta asombrada de la multitud ante el exorcismo autoritativo de Jesús. En Lucas 5:9 describe el asombro de Pedro ante la pesca milagrosa. En Hechos 3:10 caracteriza la reacción de los espectadores ante la sanación del mendigo cojo. El Nuevo Testamento lo emplea para la respuesta emocional de quienes son sobrecogidos por lo sobrenatural. La palabra sugiere no una mera sorpresa, sino un sobrecogimiento abrumador, casi paralizante, que reconoce la presencia del poder divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2286', 'spa', 'Mortífero, letal, que causa la muerte; venenoso o fatal; capaz de provocar la muerte.', 'Este adjetivo señala algo como mortífero o fatal, capaz de causar la muerte. En el uso clásico se aplicaba a heridas mortales, serpientes venenosas, enfermedades fatales y delitos capitales. Podía describir tanto lo inherentemente letal (como ciertos venenos) como lo potencialmente fatal (como heridas graves). Marcos lo emplea en el final largo para describir veneno mortal que no dañará a los creyentes que lo beban. El término enfatiza no el mero peligro, sino la capacidad real de causar la muerte, el poder de acabar con la vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2287', 'spa', 'Mortífero, letal, que trae o porta la muerte; fatal y venenoso.', 'Este adjetivo compuesto intensifica la noción de letalidad, describiendo algo que trae o porta la muerte consigo. Más enfático que simplemente «mortal», sugiere una cualidad activa de portar muerte. En el uso clásico se aplicaba a heridas fatales, enfermedades mortales, plantas venenosas y juicios capitales. Santiago lo emplea para describir la lengua indomable como «un mal turbulento, llena de veneno mortífero» (Santiago 3:8). El término combina el sustantivo «muerte» con una raíz que significa «llevar» o «portar», creando la imagen de algo que activamente acarrea la muerte tras de sí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2288', 'spa', 'Muerte — el cese de la vida, ya sea física, judicial o espiritual; el enemigo definitivo vencido en la resurrección de Cristo', 'θάνατος es el sustantivo griego estándar para la muerte, derivado del verbo θνῄσκω («morir»). Sus 120 apariciones en el Nuevo Testamento recorren todo el espectro de la mortalidad: muerte natural (Fil 1:20), ejecución violenta (Mt 20:18), pena de muerte judicial (Mt 26:66) y el concepto teológico de muerte espiritual como separación de Dios (Ro 6:23, «la paga del pecado es muerte»). Pablo y Apocalipsis personifican la muerte como un poder hostil que Cristo ha derrotado — «¿Dónde está, oh muerte, tu aguijón?» (1 Co 15:55) — y que será destruida al final de los tiempos (Ap 20:14, «la muerte fue arrojada al lago de fuego»).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2289', 'spa', 'El verbo griego θανατόω (thanatoo), derivado de θάνατος (''muerte''), significa causar la muerte de alguien. Sus 11 apariciones en el NT se dividen entr', 'El verbo griego θανατόω (thanatoo), derivado de θάνατος (''muerte''), significa causar la muerte de alguien. Sus 11 apariciones en el NT se dividen entre voz activa y pasiva, y esta distinción revela un patrón significativo. En la activa, agentes humanos conspiran para matar: el Sanedrín busca ''dar muerte a Jesús'' (Mt 26:59; 27:1), y Jesús advierte que ''el hermano entregará al hermano a la muerte'' (Mt 10:21). En la pasiva, el enfoque se traslada al que padece: Cristo fue ''muerto en la carne'' (1 P 3:18), los creyentes ''somos entregados a muerte todo el día'' (Ro 8:36), y Pablo extiende la metáfora: los creyentes ''murieron a la ley mediante el cuerpo de Cristo'' (Ro 7:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2290', 'spa', 'El verbo θάπτω (thaptō) significa sepultar o enterrar un cuerpo, abarcando tanto el acto físico como la obligación cultural de dar sepultura digna. El', 'El verbo θάπτω (thaptō) significa sepultar o enterrar un cuerpo, abarcando tanto el acto físico como la obligación cultural de dar sepultura digna. El mandato provocador de Jesús ''deja que los muertos entierren a sus muertos'' (Mt 8:21-22; Lc 9:59-60) resalta el costo radical del discipulado por encima del más sagrado deber filial. Los discípulos de Juan el Bautista ''tomaron el cuerpo y lo sepultaron'' (Mt 14:12). El hombre rico ''murió y fue sepultado'' (Lc 16:22), David ''murió y fue sepultado'' (Hch 2:29), y Ananías y Safira fueron sacados y sepultados (Hch 5:6, 9-10). La fórmula credo de Pablo afirma que Cristo ''fue sepultado'' (1 Co 15:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2291', 'spa', 'Taré, nombre propio; padre de Abraham en la genealogía bíblica, del hebreo posiblemente ''demora''.', 'Este nombre hebreo (תֶּרַח) identifica al padre de Abraham, quien emigró de Ur de los caldeos hacia Harán pero murió antes de llegar a Canaán. Lucas lo incluye en el registro genealógico que traza el linaje de Jesús desde Abraham hasta Adán. El relato de Génesis muestra a Taré iniciando el viaje hacia Canaán que su hijo Abraham completaría. Vivió 205 años y murió en Harán. La etimología del nombre es incierta, con propuestas que van desde «demora» hasta conexiones con la luna. La genealogía de Lucas subraya la continuidad desde la creación, a través de los patriarcas, hasta Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2292', 'spa', 'Tener confianza, estar seguro o ser osado; abarca desde la serenidad interior hasta la audacia confrontativa.', 'Verbo de fortaleza interior que el Nuevo Testamento emplea en un espectro que va desde la confianza serena hasta la osadía confrontativa. Pablo expresa su tranquila seguridad respecto a la fidelidad de los corintios (2 Co 7:16) y la confianza del creyente en estar con el Señor (2 Co 5:6, 8). El autor de Hebreos cita el Salmo 118 para declarar «el Señor es mi ayudador; no temeré» (Heb 13:6). Sin embargo, la misma palabra adquiere un filo más agudo cuando Pablo anuncia la osadía que piensa mostrar contra sus opositores (2 Co 10:1-2). El término cubre tanto la confianza reposada como el valor decidido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2293', 'spa', 'Cobrar ánimo, tener buen ánimo; exhortación imperativa que disipa el temor con esperanza confiada.', 'θαρσέω es el verbo detrás del mandato característico de Jesús «¡Ánimo!», dirigido al paralítico (Mt 9:2), a la mujer con hemorragia (Mt 9:22) y a los discípulos aterrorizados sobre el mar (Mt 14:27; Mr 6:50). Su pariente ático θαρρέω aparece en las epístolas de Pablo, pero en los Evangelios θαρσέω es casi una firma de la compasión de Jesús que sale al encuentro del miedo humano. En cada caso, la palabra transmite una seguridad cálida que invita a dejar atrás el temor y confiar en la presencia y el poder divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2294', 'spa', 'Ánimo, valentía, confianza; espíritu valeroso; fundamento para el coraje o la confianza.', 'Este sustantivo capta el espíritu valeroso y la confianza audaz: la cualidad que permite actuar ante el peligro o la dificultad. En el uso clásico abarcaba el coraje en batalla, la confianza frente a los enemigos y los motivos de esperanza. Ocasionalmente podía conllevar matices negativos de osadía o temeridad. En Hechos 28:15, los compañeros de Pablo cobran ánimo al verlo, reviviendo su valentía gracias a su presencia y fe. El término sugiere no una bravuconería imprudente, sino una confianza bien fundada que posibilita la acción valiente. Es tanto una cualidad interior como la base externa que la inspira.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2296', 'spa', 'Maravillarse, asombrarse; en voz pasiva, ser objeto de admiración; raramente, admirar con parcialidad', 'Maravillarse, asombrarse; en voz pasiva, ser objeto de admiración; raramente, admirar con parcialidad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2297', 'spa', 'Maravilloso, admirable, asombroso; extraordinario y digno de admiración y asombro.', 'Este adjetivo señala algo como maravilloso y admirable, digno de asombro y admiración. En el uso clásico describía hazañas extraordinarias, visiones prodigiosas y acontecimientos asombrosos. Mateo lo emplea para describir las cosas maravillosas que Jesús realizó y que los niños celebraban en el templo, provocando la indignación de los principales sacerdotes (Mateo 21:15). El término sugiere no simplemente algo sorprendente, sino positivamente admirable, capaz de inspirar asombro y alabanza. Está emparentado con θαῦμα (prodigio, maravilla) y θαυμάζω (maravillarse, admirarse), compartiendo esa cualidad que deja a los observadores llenos de asombro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2298', 'spa', 'Maravilloso, admirable, asombroso; describe lo que provoca asombro, ya sean las obras de Dios, sus caminos o sucesos inesperados.', 'Adjetivo reservado casi exclusivamente para aquello que provoca admiración ante la acción de Dios. Cuando Jesús cita el Salmo 118 — «esto fue obra del Señor, y es maravilloso ante nuestros ojos» (Mt 21:42; Mr 12:11) — la palabra captura el asombro ante la inversión divina. Pedro la emplea para la «luz admirable» a la cual los creyentes son llamados (1 Pe 2:9), y Apocalipsis la aplica a las obras «grandes y maravillosas» de Dios y a sus plagas (Ap 15:1, 3). En Juan 9:30 el ciego sanado la usa para expresar su incredulidad ante la ceguera espiritual de los fariseos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2299', 'spa', 'Diosa; deidad femenina o ser divino femenino; forma femenina de ''dios''.', 'Este sustantivo femenino designa a una diosa, una deidad femenina adorada en las religiones politeístas. En el uso clásico se aplicaba a figuras como Atenea, Artemisa, Afrodita y las misteriosas Erinias. Lucas lo emplea en Hechos durante el motín de Éfeso, donde los devotos de Artemisa temen que la predicación de Pablo amenace el honor de su diosa y la prosperidad económica de su ciudad (Hechos 19:27). El término aparece tanto en singular como en plural en textos clásicos, a veces con adjetivos descriptivos como «augusta» o «terrible» para especificar a qué diosa se refiere. Desde la perspectiva monoteísta bíblica, tales seres son dioses falsos y no deidades verdaderas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2300', 'spa', 'Contemplar, mirar con atención; en voz pasiva, ser visto o aparecer visiblemente ante otros.', 'Contemplar, mirar con atención; en voz pasiva, ser visto o aparecer visiblemente ante otros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2301', 'spa', 'Ser hecho espectáculo, ser expuesto públicamente a la vergüenza o al ridículo; ser exhibido para humillación.', 'Este verbo designa el ser convertido en espectáculo público, generalmente de manera humillante o vergonzosa. La forma pasiva subraya que la exposición es impuesta por otros, no elegida voluntariamente. En Hebreos se emplea para describir a creyentes que soportaron humillación pública y persecución por su fe. La metáfora teatral sugiere ser convertido en objeto de entretenimiento o escarmiento ante las multitudes. En el uso clásico incluía actuaciones escénicas reales, pero el contexto bíblico enfatiza la exposición pública involuntaria y degradante, no una actuación voluntaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2302', 'spa', 'teatro, anfiteatro; lugar de espectáculo público; en sentido figurado, un espectáculo o exhibición', 'Esta palabra designa principalmente la estructura física del teatro, pero se extiende metafóricamente para significar un espectáculo público. En Hechos 19:29 y 19:31 se refiere al teatro real de Éfeso, una enorme construcción con capacidad para miles de personas, donde se reunió el tumulto de los plateros. En 1 Corintios 4:9 Pablo la emplea metafóricamente: los apóstoles han sido puestos como espectáculo ante el mundo, los ángeles y los hombres, como condenados exhibidos en la arena. El uso paulino evoca la práctica romana de las ejecuciones públicas como entretenimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2303', 'spa', 'Azufre (piedra de azufre); sustancia combustible asociada al juicio divino, la purificación y el fuego apocalíptico.', 'θεῖον designa el azufre, el mineral amarillo de olor penetrante asociado desde antiguo con la actividad volcánica y el castigo divino. En Lucas 17:29 llueve del cielo sobre Sodoma, evocando Génesis 19. Apocalipsis recurre abundantemente a esta imagen: el azufre acompaña al fuego y humo de la caballería demoníaca (Ap 9:17-18), atormenta a los impíos junto con el fuego (Ap 14:10; 20:10) y llena el lago del juicio final (Ap 19:20; 21:8). El término mantiene una identificación mineral directa, pero su carga teológica lo convierte en símbolo por excelencia de la ira purificadora de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2304', 'spa', 'divino, de Dios; perteneciente a la deidad o procedente de ella', 'Este adjetivo describe lo que pertenece a Dios, procede de él o se relaciona con la naturaleza divina. En Hechos 17:29 Pablo argumenta que no debemos pensar que el «ser divino» (τὸ θεῖον) se asemeje a imágenes de oro o plata. En 2 Pedro 1:3 el «poder divino» de Dios ha concedido todo lo necesario para la vida y la piedad. En 2 Pedro 1:4 se promete a los creyentes participar de la «naturaleza divina». Mientras la filosofía griega usaba τὸ θεῖον en sentido abstracto, el Nuevo Testamento vincula firmemente la divinidad al Dios personal revelado en Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2305', 'spa', 'Naturaleza divina, divinidad, deidad; la cualidad esencial de ser divino; carácter divino.', 'Este sustantivo abstracto designa la naturaleza divina o la cualidad de la divinidad: aquello que hace que Dios sea Dios. Se distingue de θεότης (la plenitud de la deidad) en que enfatiza la cualidad divina general en lugar de la deidad absoluta en sí. Pablo lo emplea en Romanos para describir cómo los atributos invisibles de Dios, incluida su naturaleza divina, se comprenden a través de la creación. El término aparece en la LXX y en escritos cristianos posteriores para describir el carácter o cualidad divina. Es más abstracto que θεός (un dios) o θεότης (la deidad), y se centra en la esencia o cualidad de lo divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2306', 'spa', 'Sulfuroso, semejante al azufre; que tiene el color amarillo o las propiedades del azufre.', 'Este adjetivo describe algo sulfuroso, que posee el color, olor o propiedades del azufre. En el uso clásico se aplicaba principalmente a aguas sulfurosas y objetos de color amarillo. Juan lo emplea en Apocalipsis para describir las corazas amarillas de la caballería demoníaca, vinculándolas visualmente con el fuego y el azufre que brotan de las bocas de los caballos. El término enfatiza tanto el color amarillo intenso como la asociación con el azufre, sustancia portadora de juicio, frecuentemente emparejada con el fuego en la imaginería bíblica de la ira divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2307', 'spa', 'θέλημα — voluntad, deseo, propósito; lo que alguien quiere, pretende o determina que suceda', 'El sustantivo neutro θέλημα (''voluntad'') expresa el deseo, la intención o el propósito de una persona, y de manera suprema la voluntad de Dios. Derivado del verbo θέλω (''querer''), aparece 63 veces en el Nuevo Testamento y es teológicamente central: Jesús enseña a orar ''hágase tu voluntad'' (Mt 6:10), declara que solo quien hace la voluntad del Padre entrará en el reino (Mt 7:21), y en Getsemaní somete su propia voluntad a la del Padre (Mt 26:42). Pablo lo emplea tanto para el propósito salvífico de Dios (Ef 1:5, 9, 11) como para los deseos humanos (Ef 2:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2308', 'spa', 'Voluntad, volición, deseo; el acto de querer o decidir; intención o determinación soberana.', 'Este sustantivo designa el acto de querer o decidir, el ejercicio de la volición. Aunque está emparentado con θέλημα (el contenido de lo que se quiere), θέλησις enfatiza el acto o proceso mismo de querer. En el uso clásico se distinguía como la acción de querer frente a lo querido. En Hebreos se emplea para describir cómo el Espíritu Santo distribuyó los dones espirituales conforme a su propia voluntad, es decir, su elección soberana. El término aparece en discusiones filosóficas sobre la naturaleza de la volición y en la LXX para los propósitos deliberados de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2309', 'spa', 'Querer, desear, estar dispuesto o proponerse; el verbo griego principal para expresar deseo, consentimiento, intención y deleite', 'El verbo θέλω es el instrumento fundamental del Nuevo Testamento para expresar la voluntad humana y divina. Jesús lo emplea para revelar el corazón del Padre («misericordia quiero y no sacrificio», Mt 9:13), para probar el compromiso de quienes desean seguirlo («si alguno quiere venir en pos de mí», Mt 16:24) y para manifestar su propia voluntad compasiva («quiero, sé limpio», Mt 8:3). Lo que hace especialmente rico a θέλω es su capacidad de matizarse desde la mera preferencia, pasando por la firme resolución, hasta la determinación divina, a veces dentro de un mismo discurso. Pablo explota magistralmente esta amplitud en Romanos 7:15-21, donde el «querer» el bien y el «no querer» el mal trazan el conflicto interior de la voluntad humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2310', 'spa', 'Cimiento o base sobre la cual descansa una estructura; usado literalmente para edificios y figuradamente para los fundamentos doctrinales o espiritual', 'Cimiento o base sobre la cual descansa una estructura; usado literalmente para edificios y figuradamente para los fundamentos doctrinales o espirituales. Tanto en el griego clásico como en el bíblico, θεμέλιος designa la hilada inferior de piedras sobre la cual se levanta un edificio. Jesús contrasta una casa edificada sobre roca con una que carece de cimiento (Lc 6:48-49), y Pablo habla de Cristo como el único cimiento verdadero (1 Co 3:11). La palabra se extiende naturalmente a la metáfora: los apóstoles y profetas forman el cimiento de la casa de Dios (Ef 2:20), y la Jerusalén celestial tiene doce piedras de cimiento inscritas con sus nombres (Ap 21:14, 19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2311', 'spa', 'Poner fundamento, establecer firmemente; cimentar algo de manera segura, literal o espiritualmente', 'Significa poner un fundamento o establecer algo sobre una base firme. Aunque se origina en el lenguaje de la construcción —asentar piedras para un edificio—, el Nuevo Testamento lo extiende con fuerza al terreno espiritual. Cristo cimenta a los creyentes en el amor (Ef 3:17), la fe debe permanecer fundada e inconmovible (Col 1:23), y Dios mismo establecerá a quienes sufren (1 Pe 5:10). Las traducciones al español ''cimentados'' y ''fundados'' captan bien tanto el registro arquitectónico como el metafórico de este verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2312', 'spa', 'Enseñado por Dios, instruido divinamente; que tiene a Dios como maestro; receptor de enseñanza divina.', 'Este adjetivo compuesto describe a quienes son enseñados por Dios mismo, no meramente por instructores humanos. Combina θεός (Dios) con διδακτός (enseñado), creando el hermoso concepto de instrucción divina. Pablo lo usa una sola vez, refiriéndose a creyentes que han sido directamente enseñados por Dios a amarse unos a otros. El término implica una pedagogía divina directa: la instrucción interna del Espíritu más que la enseñanza externa humana solamente. Hace eco de la profecía de Isaías de que todo el pueblo de Dios sería enseñado por el Señor, promesa que Jesús aplicó a sus discípulos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2313', 'spa', 'Luchar contra Dios, oponerse a la deidad; hacer guerra contra los propósitos o representantes divinos.', 'Este verbo compuesto significa luchar contra Dios: oponerse a los propósitos divinos, resistir la obra de Dios o batallar contra la deidad misma. Combina θεός (Dios) con μαχέομαι (luchar), creando un término para la guerra más fútil que pueda emprenderse. Escribas y fariseos lo emplean en Hechos, advirtiendo que oponerse a los apóstoles podría significar estar combatiendo contra Dios mismo. En el uso clásico aparecía en textos sobre batallas mitológicas contra los dioses. En el contexto bíblico, sugiere la insensatez y el peligro de resistir lo que Dios está haciendo, ya sea por ignorancia o por rebeldía deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2314', 'spa', 'Luchadores contra Dios, opositores de los propósitos divinos; rebeldes contra la deidad.', 'Este adjetivo compuesto designa a quienes luchan contra Dios: opositores de los propósitos divinos y rebeldes contra la deidad. Combina los mismos elementos que el verbo θεομαχέω pero en forma adjetival, describiendo una cualidad característica en lugar de una acción. En el uso clásico se aplicaba a los gigantes mitológicos que guerreaban contra los dioses. Gamaliel lo emplea en Hechos, advirtiendo al Sanedrín que si la obra de los apóstoles proviene de Dios, oponerse a ella los convertiría en luchadores contra Dios, una batalla que no pueden ganar. El término sugiere tanto la futilidad como el peligro de resistir los propósitos divinos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2315', 'spa', 'Inspirado por Dios, exhalado por Dios; que tiene su origen en el aliento o espíritu divino.', 'Este compuesto único describe la Escritura como «exhalada por Dios»: no meramente inspirada por él, sino procedente de su propio aliento. Combina θεός (Dios) con πνέω (soplar, respirar), creando la poderosa imagen del aliento de Dios produciendo la Escritura. Pablo lo utiliza en su declaración clásica sobre la naturaleza y el propósito de la Escritura en 2 Timoteo. El término enfatiza el origen divino sin excluir la autoría humana: es la palabra exhalada por Dios, portadora de su autoridad y poder. Este hápax legómenon ha moldeado profundamente la comprensión cristiana de la inspiración bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2316', 'spa', 'Dios; el único Dios verdadero de Israel y de la fe cristiana; también usado para deidades paganas y figuradamente de figuras con autoridad', 'El término griego para Dios, usado principalmente para el Dios único del monoteísmo judeocristiano, pero también aplicable a dioses paganos del politeísmo grecorromano, y metafóricamente a cualquier figura que ejerce autoridad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2317', 'spa', 'Piedad, reverencia hacia Dios; devoción religiosa y temor piadoso; adoración temerosa de Dios.', 'Este sustantivo denota reverencia hacia Dios, piedad práctica y devoción religiosa expresada en adoración y servicio. Combina la reverencia (σέβομαι) con su objeto (θεός) para crear un término que describe el temor y servicio apropiados hacia Dios. En el uso clásico enfatizaba el temor religioso y la adoración de los dioses. Pablo lo emplea en 1 Timoteo para describir las buenas obras apropiadas para mujeres que profesan piedad. Sugiere no mera religiosidad externa, sino una reverencia genuina que moldea la conducta. El término aparece en contextos que enfatizan la santidad práctica que fluye de una adoración correcta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2318', 'spa', 'Temeroso de Dios, reverente, piadoso; quien teme y adora a Dios; religiosamente devoto.', 'Este adjetivo describe a alguien que teme a Dios en el sentido de adoración reverente y obediencia devota. En el uso clásico se aplicaba a personas religiosamente devotas y piadosas. En el Evangelio de Juan aparece en el argumento teológico del hombre que había sido ciego: Dios escucha a los piadosos, no a los pecadores. El término sugiere una piedad práctica y reverencia expresada en adoración y obediencia. En contextos judíos podía describir tanto a judíos como a gentiles temerosos de Dios que adoraban al Dios de Israel sin haberse convertido plenamente al judaísmo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2319', 'spa', 'Aborrecido por Dios o que aborrece a Dios; enemigo de la divinidad; odiado por Dios u odiador de Dios.', 'Este adjetivo compuesto puede significar ''aborrecido por Dios'' (sentido pasivo) u ''odiador de Dios'' (sentido activo). A diferencia del uso clásico, que enfatizaba ser aborrecido por los dioses, Pablo probablemente emplea el sentido activo: quienes odian a Dios. Aparece en Romanos dentro de un catálogo de vicios que describe a la humanidad caída sin la gracia. El término combina θεός con στυγέω (odiar con horror o repugnancia), sugiriendo no simple aversión sino una hostilidad intensa o un aborrecimiento divino. Ya sea describiendo a quienes Dios aborrece o a quienes aborrecen a Dios, marca la ruptura relacional definitiva entre Creador y criatura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2320', 'spa', 'Deidad, divinidad; la plenitud y esencia de la naturaleza divina; deidad absoluta.', 'Este sustantivo denota la deidad en sí misma: la esencia y naturaleza plena de la divinidad, no meramente cualidades divinas. Se distingue de θειότης (naturaleza divina en general) al enfatizar la totalidad de lo que hace que Dios sea Dios. Pablo lo emplea en Colosenses para declarar que en Cristo habita corporalmente toda la plenitud de la Deidad. El término no sugiere simplemente atributos divinos, sino la esencia completa de la divinidad concentrada en Cristo. Aparece en discusiones filosóficas y teológicas sobre la naturaleza de la divinidad, subrayando la realidad integral del ser divino más que cualidades divinas dispersas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2322', 'spa', 'servicio, cuidado, atención; sanación, tratamiento médico; servidumbre doméstica en conjunto', 'Este sustantivo significa fundamentalmente «servicio» o «cuidado», con usos especializados para el tratamiento médico, el servicio religioso y el personal doméstico. Lucas lo emplea para el ministerio de sanación de Jesús (Lucas 9:11) y metafóricamente para el servicio fiel en el hogar (Lucas 12:42). Apocalipsis 22:2 habla de hojas del árbol «para la sanidad de las naciones». El uso clásico incluye el servicio a los dioses, el cuidado de padres e hijos, el tratamiento médico y el cortejo interesado. En el Nuevo Testamento, servicio y sanación se vinculan conceptualmente: ambos son cuidado ofrecido para suplir una necesidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2323', 'spa', 'Sanar, curar o restaurar la salud; raramente, servir o atender las necesidades de alguien (sentido clásico que sobrevive una vez en Hechos)', 'Sanar, curar o restaurar la salud; raramente, servir o atender las necesidades de alguien (sentido clásico que sobrevive una vez en Hechos)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2324', 'spa', 'Servidor, asistente, ministro; quien sirve con devoción y dignidad; compañero fiel en el servicio.', 'Este sustantivo describe a un servidor o asistente, particularmente uno que sirve de manera voluntaria y devota. En el uso clásico abarcaba desde escuderos militares y servidores personales hasta adoradores al servicio de las deidades. Sugiere un servicio más personal que el término común para esclavo (δοῦλος), enfatizando la devoción voluntaria y el compañerismo en el servicio. Hebreos lo emplea para describir el papel de Moisés en la casa de Dios: un siervo de confianza que administraba el hogar divino. El término porta dignidad a la vez que reconoce una posición subordinada, siendo apropiado para describir un servicio honroso a un superior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2325', 'spa', 'Cosechar, segar; cortar y recoger una cosecha, usado literalmente de la agricultura y figuradamente de las consecuencias espirituales.', 'Cosechar, segar; cortar y recoger una cosecha, usado literalmente de la agricultura y figuradamente de las consecuencias espirituales.');